(1,1,'Vřídelní kolonáda','Kolonáda nad Vřídlem – nejteplejším a nejsilnějším karlovarským pramenem (72 °C), který tryská až do výšky 12 metrů. Ochutnat můžete i další prameny. Vstup zdarma.','SIGHTSEEING',30,50.22300000,12.88330000,'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/50/Karlovy_Vary_V%C5%99%C3%ADdeln%C3%AD_kolon%C3%A1da_duben_2019_%281%29.jpg/960px-Karlovy_Vary_V%C5%99%C3%ADdeln%C3%AD_kolon%C3%A1da_duben_2019_%281%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','19:00',0,'',1,'EASY','MANUAL',NULL,NULL,1,NULL,NULL,NULL),
