(138,31,'Zámek Kynžvart','Původně raně barokní zámek, nynější klasicistní podoba pochází z přestavby v letech 1821 - 1835. Reprezentativní zámecké sídlo je spojeno se jménem rakouského kancléře Metternicha. Návštěvníci zde mohou dnes obdivovat mimořádně cenné interiéry - kancléřovu pracovnu se slavným rozkládacím stolem, knihovnu, kulečníkový salón nebo jídelnu s rodinnými portréty. Velkou pozornost přitahuje také kabinet kuriozit, ve kterém je k vidění například hřeben Marie Terezie, egyptské mumie, psací stůl Alexandra Dumase nebo vycházková hůl císaře Josefa I. Přístup: v otevírací době.','SIGHTSEEING',90,50.00446800,12.60523300,'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d7/Z%C3%A1mek_Kyn%C5%BEvart_celek_1.jpg/960px-Z%C3%A1mek_Kyn%C5%BEvart_celek_1.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','09:00','17:00',150,'ZAMEK,NKP',1,'EASY','DATAZAPAD','Zámky_v_Karlovarském_kraji_WFL1:1','https://zamek-kynzvart.cz/cs',1,'Zámek 347, 354 91 Lázně Kynžvart',NULL,NULL),
(139,10,'Zámek Chyše','Zámek v obci Chyše, kulturní památka. Přístupný v provozní době, vstupné uvedeno na webových stránkách zámku.','SIGHTSEEING',90,50.10573400,13.24622800,'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2f/Chyse_zamek_park.jpg/960px-Chyse_zamek_park.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','09:00','17:00',150,'ZAMEK',1,'EASY','DATAZAPAD','Zámky_v_Karlovarském_kraji_WFL1:2','https://chyse.com/',1,'č.p. 30, 364 53 Chyše',NULL,NULL),
(140,37,'Zámek Valeč','Zámek v obci Valeč, kulturní památka. Přístupný v provozní době, vstupné uvedeno na webových stránkách zámku.','SIGHTSEEING',90,50.17483200,13.25199700,'https://www.zamek-valec.cz/pamatky/valec/fotogalerie/karusel-homepage/image-thumb__166867__OgTagImage/5q9a4138.jpg','09:00','17:00',150,'ZAMEK',1,'EASY','DATAZAPAD','Zámky_v_Karlovarském_kraji_WFL1:3','https://www.zamek-valec.cz/cs',1,'Karlovarská, 364 55 Valeč',NULL,NULL),
(142,39,'Zámek Libá','Zámek v obci Libá, kulturní památka. Přístupný v provozní době, vstupné uvedeno na webových stránkách zámku.','SIGHTSEEING',90,50.12670300,12.23376300,'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5c/Z%C3%A1mek_v_Lib%C3%A9_%C4%8Derven_2022_%281%29.jpg/960px-Z%C3%A1mek_v_Lib%C3%A9_%C4%8Derven_2022_%281%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','09:00','17:00',150,'ZAMEK',1,'EASY','DATAZAPAD','Zámky_v_Karlovarském_kraji_WFL1:5','http://www.libaczech.cz/#/',1,'č.p. 9, 351 31 Libá',NULL,NULL),
(144,40,'Zámek Hazlov','Zámek v obci Hazlov, kulturní památka. Částečně přístupný, sídlo obecního úřadu a knihovny; kavárna. Veřejnosti běžně nepřístupné - v plánu jako krátká zastávka zvenku.','SIGHTSEEING',20,50.15784200,12.27390900,'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/Z%C3%A1mek_Hazlov_leden_2020_%286%29.jpg/960px-Z%C3%A1mek_Hazlov_leden_2020_%286%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'ZAMEK,ZVENKU',1,'EASY','DATAZAPAD','Zámky_v_Karlovarském_kraji_WFL1:7','https://www.obechazlov.cz/obec-hazlov/informace-o-obci/zamek/',0,'č.p. 310, 351 32 Hazlov',NULL,NULL),
(145,5,'Hrad a zámek Bečov nad Teplou','Pozdně gotický hrad a barokní zámek. Původně mohutné věže tvoří jednotný areál s renesančním palácem, v 18. století k němu v předhradí přibyl zámek s knihovnou a zámeckou kaplí. Hlavní atrakcí na zámku a po českých korunovačních klenotech nejvzácnější ukázkou středověkého šperkařství je Relikviář sv. Maura, zhotoven v první třetině 13. století, pro klášter ve Florennes. Přístup: v otevírací době.','SIGHTSEEING',90,50.08589500,12.83968500,'https://www.zamek-becov.cz/pamatky/becov-nad-teplou/prohlidkove-okruhy/expozice-rsm/image-thumb__157270__OgTagImage/maurbecov_02.jpg','09:00','17:00',150,'ZAMEK,HRAD,NKP',1,'EASY','DATAZAPAD','Zámky_v_Karlovarském_kraji_WFL1:8','https://www.zamek-becov.cz/cs',1,'Nám. 5. května 13, 364 64 Bečov nad Teplou',NULL,NULL),
