(155,33,'Zřícenina zámku Hammerhof (Hamrníky)','Zřícenina v obci Mariánské Lázně, kulturní památka. Zvenčí částečně přístupný, budova pro veřejnost uzavřena. Veřejnosti běžně nepřístupné - v plánu jako krátká zastávka zvenku.','SIGHTSEEING',20,49.95464900,12.68775400,NULL,'06:00','22:00',0,'ZAMEK,ZRICENINA,ZVENKU',1,'EASY','DATAZAPAD','Zámky_v_Karlovarském_kraji_WFL1:18','https://pamatkovykatalog.cz/zamek-hammerhof-s-hospodarskym-dvorem-17950512',0,'Hamrníky 1, 353 01 Mariánské Lázně',NULL,NULL),
(156,23,'Zámek Kamenný Dvůr','Zámek v obci Kynšperk nad Ohří, kulturní památka. Vstup omezený, zámek slouží jako hotel. Veřejnosti běžně nepřístupné - v plánu jako krátká zastávka zvenku.','SIGHTSEEING',20,50.10330000,12.53537000,'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e7/Kamenn%C3%BD_Dv%C5%AFr_Chateau.jpg/960px-Kamenn%C3%BD_Dv%C5%AFr_Chateau.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'ZAMEK,ZVENKU',1,'EASY','DATAZAPAD','Zámky_v_Karlovarském_kraji_WFL1:19','https://www.zamekkamennydvur.cz/',0,'Kamenný Dvůr 1, 357 51 Kynšperk nad Ohří',NULL,NULL),
(158,15,'Janův zámek Toužim','Zámek v obci Toužim, kulturní památka. Přístupné nádvoří během víkendů o letních prázdninách a během konání akcí spolku. Veřejnosti běžně nepřístupné - v plánu jako krátká zastávka zvenku.','SIGHTSEEING',20,50.05977800,12.98373300,'https://touzimskyzamek.estranky.cz/img/picture/104/zz-park2.jpg','06:00','22:00',0,'ZAMEK,ZVENKU',1,'EASY','DATAZAPAD','Zámky_v_Karlovarském_kraji_WFL1:21','https://touzimskyzamek.estranky.cz/',0,'náměstí Jiřího z Poděbrad 3, 364 01 Toužim',NULL,NULL),
