(216,1,'Císařské lázně','Císařské lázně patří k největším a umělecky nejbohatším lázeňským domům v Karlových Varech. Byly vybudovány v letech 1893 - 1895 jako komplexní lázeňské zařízení špičkové úrovně, ve své době nejhonosnější lázeňské zařízení Rakouska - Uherska. Jsou vybudovány v neobarkoním stylu. Přístup: v otevírací době.','SIGHTSEEING',60,50.21898200,12.88141700,'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f9/C%C3%ADsa%C5%99sk%C3%A9_l%C3%A1zn%C4%9B_01_%28cropped%29.jpg/960px-C%C3%ADsa%C5%99sk%C3%A9_l%C3%A1zn%C4%9B_01_%28cropped%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','10:00','17:00',100,'MUZEUM,NKP',1,'EASY','DATAZAPAD','Muzea_a_galerie_v_KVK_WFL1:1','https://cisarskelazne.cz/',1,'Mariánskolázeňská 306/2, 360 01 Karlovy Vary',NULL,NULL),
