(287,36,'Klášter premonstrátů Teplá','Klášter byl založen roku 1193 blahoslaveným Hroznatou. Areál prošel složitým vývojem, nynější budovy jsou kromě kostela barkoní. K areálu kláštera patří kostel Zvěstování Panně Marii. Nejpozoruhodnějším prostorem je novorenesanční sál knihovny, jehož výzdoba pochází z let 1907 - 1908. Před západním průčelím kostela stojí raně barokní sýpka z roku 1680 s věží a hospodářské budovy s raně barokní bránou z 2. poloviny 17. století. Osmiboký letní pavilón v severozápadním nároží areálu pochází z 18. století. Areál dotváří několik barokních soch. Tepelský klášter je nejvýznamnější klášter na území Karlovarského kraje a řadí se mezi nejhodnotnější komplexy v rámci celé Českérepubliky. Přístup: v otevírací době.','SIGHTSEEING',45,49.96635100,12.87825100,'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c6/Kl%C3%A1%C5%A1ter_Tepl%C3%A1_celek_2.jpg/960px-Kl%C3%A1%C5%A1ter_Tepl%C3%A1_celek_2.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','09:00','17:00',100,'NKP,KOSTEL',1,'EASY','DATAZAPAD','Národní_kulturní_památky_v_KVK_WFL1:1','https://klastertepla.cz/',0,'Klášter Teplá 1, 364 61 Teplá',NULL,NULL),
(288,69,'Poutní areál Chlum Svaté Maří','Poutní areál Chlum Svaté Maří s kostelem Nanebevzetí Panny Marie a sv. Máří Magdalény patří mezi klíčová poutní místa na hranicích Čech a Bavorska. Na konečné podobě barokního areálu, který vznikl mezi léty 1687 – 1728 na místě gotického kostela, se podíleli především Jean Baptista Mathey a Kryštof Dientzenhofer. Přístup: v otevírací době.','SIGHTSEEING',45,50.14997100,12.53601000,'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/03/Poutn%C3%AD_are%C3%A1l_Chlum_Svat%C3%A9_Ma%C5%99%C3%AD_ambit_leden_2020_%281%29.jpg/960px-Poutn%C3%AD_are%C3%A1l_Chlum_Svat%C3%A9_Ma%C5%99%C3%AD_ambit_leden_2020_%281%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','00:00','23:59',0,'NKP,KOSTEL',1,'EASY','DATAZAPAD','Národní_kulturní_památky_v_KVK_WFL1:2','https://mariakulm.eu/',0,'náměstí J. W. Goetheho 1/1, 357 09 Chlum Svaté Maří',NULL,NULL),
(291,66,'Dlouhá stoka ve Slavkovském lese','24 km dlouhý umělý vodní kanál vybudovaný v letech 1531 – 1536 sloužil k plavení dřeva z oblasti kynžvartských lesů do slavkovských báňských provozů. Celé vodní dílo původně tvořila kromě hlavního kanálu, který vedl z Kladské až do Horního Slavkova, řada vedlejších větví s devíti napájecími rybníky. Přístup: volně přístupné.','SIGHTSEEING',45,50.02653300,12.67558300,'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/74/Dlouh%C3%A1_stoka.jpg/960px-Dlouh%C3%A1_stoka.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'NKP,TECHNIKA',1,'EASY','DATAZAPAD','Národní_kulturní_památky_v_KVK_WFL1:6','https://www.kudyznudy.cz/aktivity/dlouha-stoka-ve-slavkovskem-lese',0,'357 31 Krásno',NULL,NULL),
(292,7,'Blatenský vodní příkop','Vynikajícím příkladem technického umu vodohospodářů 16. století je dodnes funkční Blatenský vodní příkop, nejdelší báňský vodní přivaděč v české části Krušných hor. Byl vybudován v letech 1540–1544 v délce téměř 13 km a až do 19. století zajišťoval pohonnou vodu pro desítky důlních a úpravárenských provozů od Božího Daru až po Horní Blatnou. Příkop je až 2 m široký a až 1 m hluboký, jeho koryto je zpevněno dřevěným bedněním. Po obou stranách jsou navršeny náspy. Unikátní jsou zejména četné objekty k regulaci průtoku vody. Přístup: volně přístupné.','SIGHTSEEING',45,50.41272700,12.90205700,'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6c/Horn%C3%AD_Blatn%C3%A1_Blatensk%C3%BD_p%C5%99%C3%ADkop.jpg/960px-Horn%C3%AD_Blatn%C3%A1_Blatensk%C3%BD_p%C5%99%C3%ADkop.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'NKP,TECHNIKA',1,'EASY','DATAZAPAD','Národní_kulturní_památky_v_KVK_WFL1:7','https://www.bozidar.cz/cs/izajimavosti/pamatky-a-historie/blatensky-vodni-prikop.html',0,'362 62 Boží Dar',NULL,NULL),
(295,4,'Důl Mauritius','Důl Mauritius na Hřebečné poblíž krušnohorského města Abertamy představuje lokalitu se zachovalými pozůstatky důlních děl průřezově z celého období těžby zdejšího ložiska cínu tj. od 16. do počátku 20. století. V rozsáhlých úsecích dolu jsou zachovány autentické profily chodeb se stopami po želízku a mlátku (tzv. křesanice). V několika místech jsou zde zachovány stopy po dobývání tzv. sázením ohněm. Přístup: v otevírací době.','SIGHTSEEING',45,50.38712100,12.83104900,NULL,'09:00','17:00',100,'NKP,TECHNIKA',1,'EASY','DATAZAPAD','Národní_kulturní_památky_v_KVK_WFL1:10','https://www.dulmauritius.cz/',0,'Pohraničníků 32, 362 35 Abertamy',NULL,NULL),
(296,31,'Kynžvartská daguerrotypie','Jedná se o první prakticky užívanou komplexní metodu fotografie, kterou objevil francouzský malíř a vynálezce Louis Daguerre. Na vzácné památce je jeho věnování kancléři Metternichovi, který ji zařadil do svého kynžvartského zámeckého muzea. V dubnu 2018 byla fotografie zapsaná na prestižní seznam dokumentů UNESCO Paměť světa. Přístup: v otevírací době.','SIGHTSEEING',45,50.00445000,12.60523900,'https://www.zamek-kynzvart.cz/pamatky/kynzvart/fotografie/Karusel/image-thumb__94501__OgTagImage/04_karusel_Kynzvart_web.jpg','09:00','17:00',100,'NKP,UNESCO',1,'EASY','DATAZAPAD','Národní_kulturní_památky_v_KVK_WFL1:11','https://www.zamek-kynzvart.cz/cs/pamatka-unesco',0,'Nám. 5. května 13, 354 91 Lázně Kynžvart',NULL,NULL),
(297,1,'Kostel svaté Máří Magdalény v Karlových Varech','Barokní kostel z let 1732 - 1736, postavený křížovníky s červenou hvězdou podle projektu Kiliána Ignáce Dientzenhofera. K novému zastřešení věží po požáru z roku 1795 došlo až roku 1861. Nynější terasy a schodiště před kostelem pocházejí z roku 1897. Jedna z nejhodnotnějších sakrálních staveb českého dynamického baroka, s velmi kvalitním vnitřním zařízením. Přístupný v době konání církevních bohoslužeb a kulturních akcí. Veřejnosti běžně nepřístupné - v plánu jako krátká zastávka zvenku.','SIGHTSEEING',20,50.22270300,12.88446200,'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f2/St._Mary_Magdalene%27s_Church2_%28Karlovy_Vary%29_2009-08-08.jpg/960px-St._Mary_Magdalene%27s_Church2_%28Karlovy_Vary%29_2009-08-08.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'NKP,ZVENKU,KOSTEL',1,'EASY','DATAZAPAD','Národní_kulturní_památky_v_KVK_WFL1:12','https://www.karlovyvary.cz/cs/kostel-sv-mari-magdaleny',0,'náměstí Svobody 217/2, 360 01 Karlovy Vary',NULL,NULL),
(300,2,'Chebská falc','Románská císařská falc (opevněný palác), jediná v Čechách, vznikla přestavbou původního hradu ve 2. pol. 12. století. Dominantní je 18,5 m vysoká Černá věž z tufového kamene z nedaleké Komorní hůrky. Ojedinělá je dvoupatrová kaple sv. Erharda a sv. Uršuly, kde je jedno podlaží postaveno v románském a druhé v gotickém slohu. Přístup: v otevírací době.','SIGHTSEEING',45,50.08115100,12.36603000,'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4e/Cheb%2C_hrad%2C_falc_II.jpg/960px-Cheb%2C_hrad%2C_falc_II.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','09:00','17:00',100,'NKP',1,'EASY','DATAZAPAD','Národní_kulturní_památky_v_KVK_WFL1:15','https://www.hrad-cheb.cz/cz/hrad_cheb',0,'Dobrovského 2062/21, 350 02 Cheb',NULL,NULL),
(309,2,'Kostel sv. Mikuláše a Alžběty v Chebu','Věžní vyhlídka s točitým schodištěm se 170 schody a zvonicí. Přístupná v otevírací době - mimo pravidelné bohoslužby denně od jara do podzimu mezi 10:00 a 17:00 h, dobrovolný poplatek.','SIGHTSEEING',30,50.08075600,12.37036200,'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/Cheb_velk%C3%BD_kostel_1.jpg/960px-Cheb_velk%C3%BD_kostel_1.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','09:00','18:00',100,'KOSTEL,ROZHLEDNA',1,'EASY','DATAZAPAD','Náboženské_památky_v_Karlovarském_kraji_WFL1:3','https://farnostcheb.cz/clanek.php?id=85',1,'Kostelní náměstí 188/15, 350 02 Cheb',NULL,NULL),
