(318,5,'Relikviář svatého Maura, Bečov nad Teplou','Relikviář svatého Maura je výjimečnou zlatnickou památkou na území České republiky. Co do hodnoty, je tento předmět srovnatelný s korunovačními klenoty. Jeho vypátrání v roce 1985 se považuje za jeden z největších nálezů 20. století v tehdejším Československu. Přístup: v provozní době, zpoplatněný.','SIGHTSEEING',30,50.08614000,12.83937900,'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/28/Relikvi%C3%A1%C5%99_Sv._Maura%2C_expozice_nalezen%C3%AD_relikvi%C3%A1%C5%99e_%282024%29_02.jpg/960px-Relikvi%C3%A1%C5%99_Sv._Maura%2C_expozice_nalezen%C3%AD_relikvi%C3%A1%C5%99e_%282024%29_02.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','09:00','18:00',100,'KOSTEL,ATRAKCE',1,'EASY','DATAZAPAD','Náboženské_památky_v_Karlovarském_kraji_WFL1:12','https://www.zamek-becov.cz/cs/becovske-poklady/relikviar-svateho-maura',1,'nám. 5. května 13, 364 64 Bečov nad Teplou',NULL,NULL),
