(336,74,'Železniční viadukt Pernink','Kamenný železniční most s šesti oblouky, postavený v letech 1898–1899, který překlenuje údolí poblíž obce Pernink. Zařazen mezi nejvýše položené železniční stavby svého druhu v České republice.','SIGHTSEEING',45,50.36362100,12.77388400,'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/62/Pernink_perninsk%C3%BD_viadukt.jpg/960px-Pernink_perninsk%C3%BD_viadukt.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','00:00','23:59',0,'TECHNIKA',1,'EASY','DATAZAPAD','Technické_památky_v_KVK_WFL1:3','https://www.kudyznudy.cz/aktivity/kamenny-viadukt-v-perninku',0,'362 35 Pernink',NULL,NULL),
(337,7,'Štola Johannes','Historická důlní štola v Krušných horách u Božího Daru. Mimořádně zachovalý komplex důlních děl z rudného revíru Zlatý Kopec a ukazuje 500letou historii hornictví v podzemních komorách obrovských rozměrů.','SIGHTSEEING',45,50.43297900,12.87135200,'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/07/Zlat%C3%BD_Kopec_%C5%A1tola_Hermann.jpg/960px-Zlat%C3%BD_Kopec_%C5%A1tola_Hermann.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','00:00','23:59',0,'TECHNIKA',1,'EASY','DATAZAPAD','Technické_památky_v_KVK_WFL1:4','https://www.stolajohannes.cz/cs/',0,'362 62 Boží Dar',NULL,NULL),
(338,67,'Radošovský krytý most','Krytý dřevěný silniční most přes řeku Ohři v Radošově (součást Kyselky) je považován za jeden z nejstarších dřevěných mostů ve střední Evropě. Most je vybaven šindelovou střechou a malými okénky, které osvětlují jeho vnitřní prostor.','SIGHTSEEING',45,50.27574800,12.99475600,'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/16/Rado%C5%A1ovsk%C3%BD_most.jpg/960px-Rado%C5%A1ovsk%C3%BD_most.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','00:00','23:59',0,'TECHNIKA',1,'EASY','DATAZAPAD','Technické_památky_v_KVK_WFL1:5','https://www.obeckyselka.cz/most-radosov',0,'362 72 Kyselka',NULL,NULL),
(339,54,'Vysoká pec v Šindelové','11 metrů vysoká kamenná stavba s nástavbou z cihel a struskových tvárnic, která je jedním z posledních dokladů tradiční výroby železa v dřevouhelných pecích v Čechách.','SIGHTSEEING',45,50.31698400,12.59993200,'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/de/%C5%A0indelov%C3%A1_vysok%C3%A1_pec_%C4%8Dervenec_2020_%281%29.jpg/960px-%C5%A0indelov%C3%A1_vysok%C3%A1_pec_%C4%8Dervenec_2020_%281%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'TECHNIKA',1,'EASY','DATAZAPAD','Technické_památky_v_KVK_WFL1:6','https://www.hut-sindelova.cz/',0,'358 01 Šindelová',NULL,NULL),
(340,22,'Městská jatka Kraslice','Architektonicky cenný a památkově chráněný areál z počátku 20. století, který sloužil k porážce dobytka. Nachází se zde dochované secesní budovy s původním vnitřním strojním zařízením pro chlazení a výrobu ledu.','SIGHTSEEING',45,50.31822200,12.51770900,'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1a/Kraslice_m%C4%9Bstsk%C3%A1_jatka_%282%29.jpg/960px-Kraslice_m%C4%9Bstsk%C3%A1_jatka_%282%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','00:00','23:59',0,'TECHNIKA',1,'EASY','DATAZAPAD','Technické_památky_v_KVK_WFL1:7','https://www.kraslice.cz/prakticke-informace/pro-turisty/vyznamne-kulturni-pamatky/kraslice/mestska-jatka-1751cs.html',0,'U Elektrárny 1928, 358 01 Kraslice',NULL,NULL),
(342,14,'Dům kultury v Ostrově','Významná památka socialistického realismu (s prvky tradicionalismu), která slouží jako kulturní centrum.','SIGHTSEEING',45,50.30814200,12.94902400,'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4a/D%C5%AFm_kultury_Ostrov_architektura.jpg/960px-D%C5%AFm_kultury_Ostrov_architektura.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','00:00','23:59',0,'TECHNIKA',1,'EASY','DATAZAPAD','Technické_památky_v_KVK_WFL1:9','https://www.icostrov.cz/dum-kultury-ostrov/',0,'Mírové náměstí 733, 363 01 Ostrov',NULL,NULL),
(343,17,'Hornický dům v Sokolově','Avantgardní stavba z let 1923–1925 podle projektu architekta Rudolfa Welse, významný příklad meziválečné moderny a částečně památkově chráněná budova.','SIGHTSEEING',45,50.18120300,12.64510200,'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/Sokolov_Hornick%C3%BD_d%C5%AFm_%C3%BAnor_2022_%281%29.jpg/960px-Sokolov_Hornick%C3%BD_d%C5%AFm_%C3%BAnor_2022_%281%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','00:00','23:59',0,'TECHNIKA',1,'EASY','DATAZAPAD','Technické_památky_v_KVK_WFL1:10','https://www.mdksokolov.cz/pamatky/hornicky-dum',0,'5. května 655, 356 01 Sokolov',NULL,NULL),
(344,18,'Střelecký (Starý) mlýn','Mimořádně hodnotný příklad lidové architektury chebského typu. Objekt kombinuje hrázděné přízemí s patrem a má charakteristickou sedlovou střechu s vikýři a zvoničku.','SIGHTSEEING',45,50.19539100,12.86689800,'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/97/B%C5%99ezov%C3%A1_St%C5%99eleck%C3%BD_ml%C3%BDn_%2803%29.jpg/960px-B%C5%99ezov%C3%A1_St%C5%99eleck%C3%BD_ml%C3%BDn_%2803%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','00:00','23:59',0,'TECHNIKA',1,'EASY','DATAZAPAD','Technické_památky_v_KVK_WFL1:11','https://www.karlovyvary.cz/cs/strelecky-mlyn-v-brezove',0,'Staromlýnská 26, 360 01 Březová',NULL,NULL),
(347,14,'Rudá věž smrti','Sloužila v 50. letech 20. století jako drtička a třídírna uranové rudy pro politické vězně. Je symbolem utrpení vězňů komunistického režimu v nucených pracovních táborech. Budova je součástí památky UNESCO „Hornický region Erzgebirge/Krušnohoří“.','SIGHTSEEING',45,50.32892600,12.95344200,'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/74/Vez_smrti_%28Vykmanov%29_07.JPG/960px-Vez_smrti_%28Vykmanov%29_07.JPG?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','00:00','23:59',0,'TECHNIKA',1,'EASY','DATAZAPAD','Technické_památky_v_KVK_WFL1:15','https://ruda-vez.cz/cs',0,'Dolní Žďár 103, 363 01 Ostrov',NULL,NULL),
(350,24,'Černá věž v Lokti','Původně obranná hranolová věž z 13. století, která tvořila součást středověkého hradebního systému města. Kromě výhledu na město a hrad se ve věži nachází expozice historických řemesel a kuriozit.','SIGHTSEEING',45,50.18722200,12.75577100,'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4a/Loket_M%C4%9Bstsk%C3%A9_opevn%C4%9Bn%C3%AD_%C4%8Cern%C3%A1_v%C4%9B%C5%BE_%283%29.jpg/960px-Loket_M%C4%9Bstsk%C3%A9_opevn%C4%9Bn%C3%AD_%C4%8Cern%C3%A1_v%C4%9B%C5%BE_%283%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','00:00','23:59',0,'TECHNIKA,ROZHLEDNA',1,'EASY','DATAZAPAD','Technické_památky_v_KVK_WFL1:18','https://www.loket.info/mista/pamatky/cerna-vez-6',0,'T.G.Masaryka 125, 357 33 Loket',NULL,NULL),
(352,11,'Hornická krajina Jáchymov','Dokládá staletou historii těžby rud, především stříbra a uranu. Její popis zahrnuje historické centrum města s architekturou z 16. století, ale také rozsáhlé podzemní i nadzemní památky v okolí, jako jsou doly, štoly, vodní příkopy a haldy. Krajina je jed.','SIGHTSEEING',45,50.37325100,12.91247700,'https://www.montanregion.cz/images/montanregion/historicke-centrum-mesta-jachymov/01.jpeg','00:00','23:59',0,'TECHNIKA',1,'EASY','DATAZAPAD','Technické_památky_v_KVK_WFL1:20','https://www.montanregion.cz/cs/montanregion/ceske-komponenty/18-hornicka-krajina-jachymov.html',0,'362 51 Jáchymov',NULL,NULL),
(353,4,'Hornická krajina Abertamy - Boží Dar - Horní Blatná','Rozsáhlá oblast v Krušných horách s mimořádně zachovalými pozůstatky po staletí trvající těžbě rud. Jedinečné nadzemní i podzemní památky, včetně starých dolů, propadlin, pink a vodních děl, jako je Blatenský vodní příkop, a také plánovitě založené renesa.','SIGHTSEEING',45,50.38715300,12.83080000,'https://www.montanregion.cz/images/montanregion/kategorie/dulni-revir-hrebecna.jpg#joomlaImage://local-images/montanregion/kategorie/dulni-revir-hrebecna.jpg?width=1195&height=720','00:00','23:59',0,'TECHNIKA',1,'EASY','DATAZAPAD','Technické_památky_v_KVK_WFL1:21','https://www.montanregion.cz/cs/montanregion/ceske-komponenty/19-hornicka-krajina-abertamy-bozi-dar-horni-blatna.html',0,NULL,NULL,NULL),
(355,1,'Vřídlo','1. karlovarský minerální pramen. Vřídlo je největší vývěr termominerální vody na pravém břehu říčky Teplé v Karlových Varech. Vřídlo je s teplotou 73,4 °C nejteplejším pramenem Čech. Vody Vřídla jsou svedeny do Vřídelní fontány ve Vřídelní kolonádě. Z Vřídelní fontány někdy voda pod vysokým tlakem vytryskává až do 12metrové výšky. Vody Vřídla jsou rozváděny do dalších pramenních váz ve Vřídelní kolonádě. Přístupný v otevíracích hodinách.','SIGHTSEEING',15,50.22294900,12.88374600,'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b1/V%C5%99%C3%ADdlo_005.jpg/960px-V%C5%99%C3%ADdlo_005.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:1','https://www.karlovyvary.cz/cs/vridlo-0',0,'Karlovy Vary',NULL,NULL),
(356,1,'Pramen Karla IV.','2. karlovarský minerální pramen. Pramen Karla IV., dříve známý jako Žrout, je karlovarský minerální pramen s teplotou 64 °C, volně přístupný na Tržišti v centru města. Nachází se na Tržní kolonádě a jeho objevení je spojeno s legendou o císaři Karlu IV., který si zde údajně léčil nemoci. Pramen vyvěrá z hloubky 19,5 metru a je bohatý na CO2. Jeho historie sahá až do 18. století, kdy byl původně zachycen pod starou radnicí. Přístup: obec (zastavěné území).','SIGHTSEEING',15,50.22330800,12.88287100,'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e2/Pramen_Karla_IV.jpg/960px-Pramen_Karla_IV.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:2','https://www.karlovyvary.cz/cs/pramen-karla-iv-0',0,'Karlovy Vary',NULL,NULL),
(357,1,'Dolní zámecký pramen','3. karlovarský minerální pramen. Zámecký pramen byl objeven v roce 1769 pod Zámeckou věží na Tržišti v centru Karlových Varů a poprvé zachycen roku 1797. Je vyveden do dvou pramenních váz. Jedna je umístěna na Tržní kolonádě, kde pramen o teplotě 55,6 °C vyvěrá s označením karlovarského minerálního pramene číslo tři pod názvem Zámecký dolní. Přístup: obec (zastavěné území).','SIGHTSEEING',15,50.22342500,12.88305800,'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cb/14542-Karlsbad-1912-Neue_Schlo%C3%9Fbrunn_-_Kolonade-Br%C3%BCck_%26_Sohn_Kunstverlag.jpg/960px-14542-Karlsbad-1912-Neue_Schlo%C3%9Fbrunn_-_Kolonade-Br%C3%BCck_%26_Sohn_Kunstverlag.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:3','https://www.karlovyvary.cz/cs/dolni-zamecky-pramen',0,'Karlovy Vary',NULL,NULL),
(359,1,'Tržní pramen','5. karlovarský minerální pramen. Tržní pramen je volně přístupný na Tržní kolonádě. Objeven byl v roce 1838 při stavebních pracích a je známý svou nestálostí a přerušovaným výtokem. Dosahuje teploty 62 °C a vydatnosti 4,9 litru za minutu. Přístup: obec (zastavěné území).','SIGHTSEEING',15,50.22357300,12.88329700,'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/Karlsbad%2C_Quelle_Trzni%2C_62_grd_C_IMG_6468.JPG/960px-Karlsbad%2C_Quelle_Trzni%2C_62_grd_C_IMG_6468.JPG?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:5','https://www.karlovyvary.cz/cs/trzni-pramen',0,'Karlovy Vary',NULL,NULL),
(360,1,'Mlýnský pramen','6. karlovarský minerální pramen. Mlýnský pramen je druhý nejstarší a druhý nejznámější karlovarský pramen s teplotou 56,6 °C. Historie pramene sahá až do 16. století a původně sloužil ke koupelím. Dnes je volně přístupný a nachází se v Mlýnské kolonádě. Jeho silně mineralizovaná voda je bohatá na fluoridy a křemičitou kyselinu. Unikátní je i historická mramorová deska s básní Óda na Vřídlo od Bohuslava Hasištejnského z Lobkovic. Přístup: obec (zastavěné území).','SIGHTSEEING',15,50.22487000,12.88239300,'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2d/Karlsbad%2C_Quelle_Mlynsky%2C_56_grd_C_IMG_6478.JPG/960px-Karlsbad%2C_Quelle_Mlynsky%2C_56_grd_C_IMG_6478.JPG?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:6','https://www.karlovyvary.cz/cs/mlynsky-pramen',0,'Karlovy Vary',NULL,NULL),
(361,1,'pramen Rusalka','7. karlovarský minerální pramen. Pramen Rusalka, známý původně jako Nový pramen, je karlovarský pramen s teplotou 60,2 °C. Již od 16. století využívaný k léčbě, doporučil jej k pití doktor Václav Payer. Dnes je volně přístupný v Mlýnské kolonádě, kde se nachází od roku 1881, a nabízí minerální vodu bohatou na CO2. Přístup: obec (zastavěné území).','SIGHTSEEING',15,50.22513500,12.88216000,'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/78/Karlovy_Vary_pramen_Rusalka_duben_2019_%281%29.jpg/960px-Karlovy_Vary_pramen_Rusalka_duben_2019_%281%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:7','https://www.karlovyvary.cz/cs/pramen-rusalka-0',0,'Karlovy Vary',NULL,NULL),
(362,1,'pramen Knížete Václava','8. karlovarský minerální pramen. Pramen Kníže Václav I a II, původně známý jako Bernardův pramen, se nachází na Mlýnské kolonádě. Vznikl v roce 1784 a díky výkopům se stal významným zdrojem léčivé vody. Dnes je volně přístupný z dvou míst – přímo na kolonádě (65,6 °C, 4 l/min) a před kolonádou (64,3 °C, 2 l/min) s obsahem CO₂ 500 mg/l. První vývod je označen číslem I, druhý číslem II. Přístup: obec (zastavěné území).','SIGHTSEEING',15,50.22527800,12.88195200,'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/Pramen_Kn%C3%AD%C5%BEe_V%C3%A1clav_II_%281%29.jpg/960px-Pramen_Kn%C3%AD%C5%BEe_V%C3%A1clav_II_%281%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:8','https://www.karlovyvary.cz/cs/pramen-knizete-vaclava',0,'Karlovy Vary',NULL,NULL),
(363,1,'pramen Libuše','9. karlovarský minerální pramen. Pramen Libuše, dříve známý jako Alžbětiných růží, je karlovarský minerální pramen s teplotou 62 °C. Nachází se na Mlýnské kolonádě, v srdci Karlových Varů, a je volně přístupný návštěvníkům. Vznikl díky podchycení divokých vývěrů v místě, kde dříve stála skála sv. Bernarda a kde se v minulosti koně napájeli v tzv. Koňských lázních. V současné podobě je zachycen od roku 1871 a je oblíbeným místem lázeňských hostů i turistů. Přístup: obec (zastavěné území).','SIGHTSEEING',15,50.22541600,12.88173200,'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/Karlovy_Vary_pramen_Libu%C5%A1e.jpg/960px-Karlovy_Vary_pramen_Libu%C5%A1e.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:9','https://www.karlovyvary.cz/cs/pramen-libuse-0',0,'Karlovy Vary',NULL,NULL),
(364,1,'Skalní pramen','10. karlovarský minerální pramen. Skalní pramen je volně přístupný v centru lázeňské části u Mlýnské kolonády. Vznikl v roce 1845 po úpravě Bernardovy skály a původně vyvěral přímo v řece Teplé. Dnes je jímán z hloubky 20-30 metrů a nabízí vodu o teplotě 48 °C s vysokým obsahem CO2 (650 mg/l). Jeho historie je spjata s častými úpravami a snahou o udržení vydatnosti, ovlivněnou i povodněmi a důlními vodami. Přístup: obec (zastavěné území).','SIGHTSEEING',15,50.22568300,12.88133300,'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7b/Skaln%C3%AD_pramen.JPG/960px-Skaln%C3%AD_pramen.JPG?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:10','https://www.karlovyvary.cz/cs/skalni-pramen',0,'Karlovy Vary',NULL,NULL),
(365,1,'pramen Svoboda','11. karlovarský minerální pramen. Pramen Svoboda se nachází v srdci lázeňské části u řeky Teplé. Původně nesl jména Lázeňský a Františka Josefa I., své současné jméno získal v roce 1946. Voda o teplotě 62,4 °C a vydatnosti 5 l/min je volně přístupná a chráněna v replice historického dřevěného altánu. Pramen byl objeven v roce 1865 při stavbě Lázeňského domu a od roku 1872 se využívá k pitným kúrám. Přístup: obec (zastavěné území).','SIGHTSEEING',15,50.22607300,12.88077500,'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bc/Pramen_svobody_-_detail.JPG/960px-Pramen_svobody_-_detail.JPG?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:11','https://www.karlovyvary.cz/cs/pramen-svoboda-0',0,'Karlovy Vary',NULL,NULL),
(366,1,'Sadový pramen','12. karlovarský minerální pramen. Sadový pramen, původně Císařský, je karlovarský pramen objevený v roce 1852. Nachází se na levém břehu Teplé, pod Vojenským lázeňským ústavem, a je nejsevernějším zdrojem termální vody ve městě. Vyznačuje se teplotou 41,6 °C, vydatností 1,5 l/min a vysokým obsahem CO₂, který mu dodává specifickou chuť. Přístupný je veřejnosti v Sadové kolonádě ve Dvořákových sadech. Přístup: obec (zastavěné území).','SIGHTSEEING',15,50.22742300,12.87921400,'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/11/Karlovy_Vary_Sadov%C3%A1_kolon%C3%A1da.jpg/960px-Karlovy_Vary_Sadov%C3%A1_kolon%C3%A1da.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:12','https://www.karlovyvary.cz/cs/sadovy-pramen',0,'Karlovy Vary',NULL,NULL),
(367,1,'pramen Štěpánka','14. karlovarský minerální pramen. Méně známý karlovarský minerální pramen vyvěrá v altánu Aloise Kleina v parku před parkhotelem Richmond. Stojí poněkud stranou ostatních zřídel, a tím pádem i stranou zájmu lázeňských hostů. Jeho voda se vyznačuje hlavně tím, že je studená (13°C), ale jinak má podobné složení jako ostatní prameny. To je údajně způsobeno tím, že pochází ze stejného zdroje, ale nevystupuje na povrch tak rychle a stačí se ochladit. Přístup: obec (zastavěné území).','SIGHTSEEING',15,50.21665500,12.88992200,'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/94/Karlovy_Vary_pramen_%C5%A0t%C4%9Bp%C3%A1nka_4.jpg/960px-Karlovy_Vary_pramen_%C5%A0t%C4%9Bp%C3%A1nka_4.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:13','https://www.karlovyvary.cz/cs/pramen-stepanka',0,'Karlovy Vary',NULL,NULL),
(368,1,'Hadí pramen','15. karlovarský minerální pramen, nejseverněji položený v Karlových Varech vyvěrá v Sadové kolonádě. Prvně byl zachycen v roce 2001. Voda zde vyvěrá o vydatnosti 1,8 l/min s teplotou 30°C. Pramen je volně přístupný. Přístup: obec (zastavěné území).','SIGHTSEEING',15,50.22713800,12.87875000,'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/42/Schlangenquelle_in_Karlsbad.jpg/960px-Schlangenquelle_in_Karlsbad.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:14','https://www.karlovyvary.cz/cs/hadi-pramen',0,'Karlovy Vary',NULL,NULL),
(369,1,'Železnatý pramen','16. karlovarský minerální pramen. Pramen najdeme v samostatném pavilonku na ulici Bezručova, zhruba 200 m od kruhového objezdu. Není daleko od centra lázní, ale na mnoha mapách vůbec není zaznačen a přijde k němu málokdo. Na stránkách Karlových Varů se můžeme dočíst, že voda obsahuje 1600 mg/l oxidu uhličitého a velké množství železa a arsenu. Vývěr Železnatého pramene je zde jímán již od roku 1852. Z technických důvodů pramen do odvolání uzavřen. Přístup: obec (zastavěné území).','SIGHTSEEING',15,50.23104600,12.87454900,'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fd/Karlovy_Vary_%C5%BDeleznat%C3%BD_pramen_5.jpg/960px-Karlovy_Vary_%C5%BDeleznat%C3%BD_pramen_5.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:15','https://www.karlovyvary.cz/cs/zeleznaty-pramen',0,'Karlovy Vary',NULL,NULL),
(370,33,'Křížový pramen','Pramen, původním názvem Solný, dostal své současné jméno dle dřevěného kříže, vztyčeného na místě jeho vývěru. Kříž zároveň sloužil k orientaci pro poutníky, jenž putovali za jeho jedinečnou léčivou silou. Nejvýznamnější pitný pramen Mariánských Lázní se brzy stal velmi vyhledávanou a žádanou značkou pro své léčivé účinky, takže byl dodáván do špitálů mnoha evropských měst od Petrohradu po Londýn. Pramen je volně přístupný, pavilon je otevřen denně od 6:00 do 18:00 hodin. Do pavilonu Křížového pramene, jsou přivedeny ještě dva okolní prameny, Karolinin a Rudolfův, které je zde možno také ochutnat. Přístup: obec (zastavěné území).','SIGHTSEEING',15,49.97798700,12.70660500,'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d1/Kolon%C3%A1da_K%C5%99%C3%AD%C5%BEovov%C3%A9ho_pramene.JPG/960px-Kolon%C3%A1da_K%C5%99%C3%AD%C5%BEovov%C3%A9ho_pramene.JPG?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:16','https://www.marianskelazne.cz/o-meste/prameny/krizovy-pramen/',0,'Mariánské Lázně',NULL,NULL),
(371,33,'Ferdinandův pramen','Vyvěrá v klasicistní kolonádě v lázeňském parku v městské části Úšovice. Volně přístupný. Přístup: obec (zastavěné území).','SIGHTSEEING',15,49.96232200,12.70726000,'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c3/Ferdinand%C5%AFv_pramen.JPG/960px-Ferdinand%C5%AFv_pramen.JPG?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:17','https://www.marianskelazne.cz/o-meste/prameny/ferdinanduv-pramen/',0,'Mariánské Lázně',NULL,NULL),
(372,33,'Lesní pramen','Lesní pramen (historicky Schneidsaeuerling či Větrový) je studená, silně mineralizovaná železnatá kyselka v Mariánských Lázních. Vyvěrá v pavilonu u Třebízského potoka, obsahuje hodně bikarbonátu a sodíku, a je ideální k pitným kúrám či inhalacím při léčbě onemocnění dýchacích cest a trávicího ústrojí. Klasicistní pavilon u Třebízského potoka je přístupný denně od 6:30 do 12:00 a od 16:00 do 18:00 hodin, v zimní sezoně (říjen–duben) je pavilon uzavřen, původní vývěr je volně dostupný. Přístup: obec (zastavěné území).','SIGHTSEEING',15,49.97945700,12.70051800,'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3e/Lesn%C3%AD_pramen.JPG/960px-Lesn%C3%AD_pramen.JPG?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:18','https://www.marianskelazne.cz/o-meste/prameny/lesni-pramen/',0,'Mariánské Lázně',NULL,NULL),
(373,33,'Rudolfův pramen','Rudolfův pramen vyvěral v lukách v Úšovicích a byl známý jako pramen Luční. Nazván byl dobově podle korunního prince a čekatele na trůn Rudolfa(1858 ̶ ̶ 1889). Díky Rudolfovu prameni jsou Mariánské Lázně vhodné k léčení chorob vývodních cest močových. Voda z pramene Rudolf se užívá k pitné léčbě. Rudolfův pramen je stáčen do lahví jako přírodní léčivý zdroj dle MZ ČR a je dostupný v obchodech a lékárnách. Pramen lze najít v Pavilonu Rudolfova pramene v Úšovicích (květen - září, od 6:30 do 17:00), v pavilonu Křížového pramene na kolonádě (denně 6:00 - 18:00) a Malá kolonáda Karolinina a Rudolfova pramene, naproti Společenskému domu Casino, od května do září po celý den. V souřadnicích zachycen vývěr do Úšovického potoka u Pavilonu Rudolfova pramene, který je přístupný po celý rok kdykoliv. Přístup: obec (zastavěné území).','SIGHTSEEING',15,49.95912000,12.70855000,'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/68/Pavilon_pramene.JPG/960px-Pavilon_pramene.JPG?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:19','https://www.marianskelazne.cz/o-meste/prameny/rudolfuv-pramen/',0,'Mariánské Lázně',NULL,NULL),
(374,33,'Ambrožovy prameny','Původně jediný pramen. Později rozděleno na tři samostatné vývěry. Železité prameny, užívají se zejména při chudokrevnosti. Nedaleko jsou Centrální lázně. Přístup: obec (zastavěné území).','SIGHTSEEING',15,49.97474400,12.70781800,'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/64/Ambro%C5%BEovy_prameny.JPG/960px-Ambro%C5%BEovy_prameny.JPG?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:20','https://www.marianskelazne.cz/o-meste/prameny/ambrozovy-prameny/',0,'Mariánské Lázně',NULL,NULL),
(375,33,'Karolinin pramen','Karolinin pramen, vyvěrající pod bývalou kolonádou pod kostelem Nanebevzetí panny Marie, dostal při svém objevení v roce 1809 jméno „Nový“. V roce 1817 byl přejmenován na počest manželky tehdejšího císaře Františka I. – Karoliny Augusty. Užívá se při urologických nemocech a při léčení ledvinových kamenů. Pramen je volně přístupný, je vyveden ve společné kolonádě s Rudolfovým pramenem. Přístup: obec (zastavěné území).','SIGHTSEEING',15,49.97564600,12.70731700,'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3b/Karolinin_pramen.JPG/960px-Karolinin_pramen.JPG?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:21','https://www.marianskelazne.cz/o-meste/prameny/karolinin-pramen/',0,'Mariánské Lázně',NULL,NULL),
(376,33,'Balbínův pramen','Balbínův pramen se nalézá v lese u Mariánských Lázní. Přístupný je po cestě od hotelu Agricola nebo od hřbitova v Mariánských Lázních. Pramen je sveden také do kašny v centru Mariánských Lázní. Obsahuje málo železa, proto se dá i nějakou dobu uchovávat. Pramen je mimo jiné sveden do kašny ve vstupní hale hotelu Hvězda v Mariánských Lázních. Přístup: pěšina (pěšky).','SIGHTSEEING',15,49.97420100,12.68780000,'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/96/Balbinuv_Pramen_Raseliniste_Maianske_Lazne_A.jpg/960px-Balbinuv_Pramen_Raseliniste_Maianske_Lazne_A.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:22','https://www.marianskelazne.cz/o-meste/prameny/balbinuv-pramen/',0,'Mariánské Lázně',NULL,NULL),
(377,33,'Medvědí pramen','Je známý kamennou sochou Eiblova medvěda. Původ jména kyselky pochází ze středověku, kdy se toto místo nazývalo „Medvědí brloh“ zřejmě podle doupat divokých medvědů. Pramen vyvěrá ve vykotlaném pařezu a odtud se při prvních úpravách začal odvádět potrubím o několik metrů níž, kde se postavil prameník. Pramen vyvěrá v lesoparku mezi hotelem Agricola a Balbínovým pramenem (směr Velká Hleďsebe), je volně přístupný. Přístup: pěšina (pěšky).','SIGHTSEEING',15,49.96912800,12.68434600,'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/95/Alt%C3%A1nek_s_medv%C4%9Bdem_u_pramene.JPG/960px-Alt%C3%A1nek_s_medv%C4%9Bdem_u_pramene.JPG?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:23','https://www.marianskelazne.cz/o-meste/prameny/medvedi-pramen/',0,'Mariánské Lázně',NULL,NULL),
(378,33,'pramen Farská kyselka','Voda má stálou teplotu 7 °C a obsahuje železo a hořčík. Název získala podle Farského lesa, který patřil farnosti v Rájově. Minerální pramen je schovaný v dřevěném altánku. Přístup: pěšina (pěšky).','SIGHTSEEING',15,50.01525100,12.72350200,'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/Farsk%C3%A1_kyselka_%C4%8Derven_2019_%281%29.jpg/960px-Farsk%C3%A1_kyselka_%C4%8Derven_2019_%281%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:24','https://www.marianskelazne.cz/o-meste/prameny/farska-kyselka/',0,'Mariánské Lázně',NULL,NULL),
(379,33,'Pirátův pramen','Pottovo údolí, ve kterém se pramen nalézá, dostalo svůj název pravděpodobně podle úšovického obyvatele Hanse Podda (též psáno Potta), který se zde okolo roku 1528 snažil dobývat zlato. Pirátův pramen, kterému se též říkalo Klinger nebo Skaut, je nejsevernějším a jediným přirozeně vyvěrajícím pramenem z pramenů tohoto údolí. Vyvěrá v zastřešeném dutém kmeni na levém břehu potoka. Přístup: pěšina (pěšky).','SIGHTSEEING',15,49.96332100,12.72508000,'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/Pir%C3%A1t%C5%AFv_pramen.jpg/960px-Pir%C3%A1t%C5%AFv_pramen.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:25','https://www.marianskelazne.cz/o-meste/prameny/piratuv-pramen/',0,'Mariánské Lázně',NULL,NULL),
(380,33,'pramen Edward VII.','Pramen najdeme na mariánskolázeňské Hlavní třídě před hotelem Cristal Palace (trolejbusové zastávky Cristal a Pošta), v jižní části lázeňského centra. Vyvěrá ve společném prameníku s pramenem Augustin, který se však čerpá z jiného zdroje a má odlišné vlastnosti. Spouští se kohoutkem. Přístup: obec (zastavěné území).','SIGHTSEEING',15,49.97050900,12.70295800,NULL,'06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:26','https://www.marianskelazne.cz/o-meste/prameny/pramen-edward-vii-/',0,'Mariánské Lázně',NULL,NULL),
(381,33,'Alexandřin pramen','Volně přístupný pramen vyvěrá v altánku s malou kašnou v parku Mariánských lázní. Přístup: obec (zastavěné území).','SIGHTSEEING',15,49.96923000,12.70311000,'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/ba/Pavilon_Alexandrina_Pramene_Marianske_Lazne.jpg/960px-Pavilon_Alexandrina_Pramene_Marianske_Lazne.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:27','https://www.marianskelazne.cz/o-meste/prameny/alexandrin-pramen/',0,'Mariánské Lázně',NULL,NULL),
(382,33,'pramen Augustin','Pramen najdeme na mariánskolázeňské Hlavní třídě před hotelem Cristal Palace (trolejbusové zastávky Cristal a Pošta), v jižní části lázeňského centra. Jedná se o slabší železnatou uhličitou minerálku. Vyvěrá ve společném prameníku s pramenem Edwarda VII., který se však čerpá z jiného zdroje a má odlišné vlastnosti, a spouští se kohoutkem. Přístup: obec (zastavěné území).','SIGHTSEEING',15,49.97050900,12.70295800,NULL,'06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:28','https://www.marianskelazne.cz/o-meste/prameny/pramen-augustin/',0,'Mariánské Lázně',NULL,NULL),
(383,33,'Prelátův pramen','Prelátův, dříve Pottův, pramen byl v roce 1920 vyveden do dřevěného altánu. Nyní ale mineralizovaná kyselka vytéká z pítka v podobě dřevěné sochy. Je nejníže položeným pramenem v Mariánský lázních. Pramen je volně přístupný, v zimní sezoně (říjen – duben) je uzavřen. Přístup: cesta (kolo).','SIGHTSEEING',15,49.95856900,12.71761700,'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0f/Prel%C3%A1t%C5%AFv_pramen.JPG/960px-Prel%C3%A1t%C5%AFv_pramen.JPG?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:29','https://www.marianskelazne.cz/o-meste/prameny/prelatuv-pramen/',0,'Mariánské Lázně',NULL,NULL),
(384,33,'Antoníčkův pramen','Pramen vyvěral v kořenech stromu, vedle staré cesty z Vlkovic do Úšovic, další vývěr byl níže pod silničním viaduktem (cca 1,5 m níže). V okolí bylo zřízeno skryté jímání, kterým je část pramene svedena na úšovickou náves, kde tryská v kašně s altánem a kde se dá voda bez problému nabrat. Přístup: cesta (kolo).','SIGHTSEEING',15,49.95167800,12.71645600,'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/90/Mari%C3%A1nsk%C3%A9_L%C3%A1zn%C4%9B%2C_trolejbusov%C3%A1_kone%C4%8Dn%C3%A1_Anton%C3%AD%C4%8Dk%C5%AFv_pramen.jpg/960px-Mari%C3%A1nsk%C3%A9_L%C3%A1zn%C4%9B%2C_trolejbusov%C3%A1_kone%C4%8Dn%C3%A1_Anton%C3%AD%C4%8Dk%C5%AFv_pramen.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:30','https://www.marianskelazne.cz/o-meste/prameny/antonickuv-pramen/',0,'Mariánské Lázně',NULL,NULL),
(385,3,'pramen Štěpánka','V dřevěném pavilonku v parku na Slatině nedaleko Sanatoria Klíma se nachází pramen č. 19 - Štěpánka. Určen k pitné kúře a balneaci. Přístup: pěšina (pěšky).','SIGHTSEEING',15,50.11240700,12.35702100,'https://www.frantiskovy-lazne.info/files/franlaz-item/0/300/franlaz-item_300_img_16111341041826.jpg','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:31','https://www.frantiskovy-lazne.info/cs/zajimava-mista/lecivy-pramen-stepanka_300',0,'Františkovy Lázně',NULL,NULL),
(386,3,'Luisin pramen','Pramen se nachází uprostřed pavilónu v nádrži, ve které viditelně vyvěrají asi dva silné prameny (Luisin a Studený). Přístup: obec (zastavěné území).','SIGHTSEEING',15,50.11873400,12.34850000,'https://www.frantiskovy-lazne.info/files/franlaz-item/0/290/franlaz-item_290_img_16111366496559.jpg','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:32','https://www.frantiskovy-lazne.info/cs/zajimava-mista/pramen-luisa_290',0,'Františkovy Lázně',NULL,NULL),
(387,3,'Glauberův pramen (Glauber I)','V pavilonku v těsné blízkosti Labutího jezírka se nachází pramen č. 5 - Glauber I. Otevřen v sezoně denně od 7:00-18:00. Je určen k pitné kúře. Je pramenem mírně projímavým, příjemné chuti. Osvědčuje se při katarech střevních a žaludečních. Přístup: obec (zastavěné území).','SIGHTSEEING',15,50.12044000,12.34479300,'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/eb/Franti%C5%A1kovy_L%C3%A1zn%C4%9B_pramen_Glauber_1%2C_z%C3%A1%C5%99%C3%AD_2022_%282%29.jpg/960px-Franti%C5%A1kovy_L%C3%A1zn%C4%9B_pramen_Glauber_1%2C_z%C3%A1%C5%99%C3%AD_2022_%282%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:33','https://www.frantiskovy-lazne.info/cs/zajimava-mista/glauber-i_285',0,'Františkovy Lázně',NULL,NULL),
(388,3,'Železnatý pramen','Jak vyplývá z názvu, pro pramen je charakteristický vysoký obsah železa a vývěr leží pod úrovní terénu. Minerálka vcelku chutná, má chrakteristickou železitou chuť a mírný zápach po sirovodíku. Přístup: cesta (kolo).','SIGHTSEEING',15,50.11308500,12.35787300,'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ac/Franti%C5%A1kovy_L%C3%A1zn%C4%9B_%C5%BDeleznat%C3%BD_pramen_%281%29.jpg/960px-Franti%C5%A1kovy_L%C3%A1zn%C4%9B_%C5%BDeleznat%C3%BD_pramen_%281%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:34','https://www.frantiskovy-lazne.info/cs/zajimava-mista/zeleznaty-pramen_301',0,'Františkovy Lázně',NULL,NULL),
(389,3,'Císařský pramen','Jeden z nejnověji jímaných pramenů najdete ve foyer Aquafora. Označen je číslem 3. Je jímán formou vrtu a určen je k pitné kúře a balneaci. Dostupný v otevírací době Aquafora. Přístup: pěšina (pěšky).','SIGHTSEEING',15,50.11720300,12.35738500,'https://www.frantiskovy-lazne.info/files/franlaz-item/0/289/franlaz-item_289_img_16111337870627.jpg','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:35','https://www.frantiskovy-lazne.info/cs/zajimava-mista/cisarsky-pramen_289',0,'Františkovy Lázně',NULL,NULL),
(390,35,'Císařský pramen','Nejteplejší ze studených minerálek Chebského trojúhelníku. Voda je jímána vrtem, hlubokým kolem 10 m, chuťově výborná, ale k transportu nevhodná, po stočení do nádoby dojde během několika minut k vysrážení solí a chuťové degradaci. Pramen je součástí naučné stezky rezervace SOOS, přístup k němu je v provozních hodinách zpoplatněn. Přístup: obec (zastavěné území).','SIGHTSEEING',15,50.14838700,12.40314100,'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d9/C%C3%ADsa%C5%99sk%C3%BD_pramen%2C_z%C3%A1%C5%99%C3%AD_2021_%284%29.jpg/960px-C%C3%ADsa%C5%99sk%C3%BD_pramen%2C_z%C3%A1%C5%99%C3%AD_2021_%284%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:36','https://www.estudanky.eu/1748',0,'Skalná',NULL,NULL),
(391,3,'Solný pramen','Vyvěrá na severovýchodním konci empírové kolonády z roku 1844. Přístupný zdarma v denní dobu. Vydatnost: 0,8 l/min Teplota: 11,0 ºC Volný CO2: 2180 mg/l Odparek: 2956 mg/l HCO3: 1176 mg/l ph: 6,01 Vznik: 1819 Hloubka: 2,8 m. Přístup: obec (zastavěné území).','SIGHTSEEING',15,50.11615200,12.35620100,'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d2/Fr_l%C3%A1zn%C4%9B_Soln%C3%BD_pramen.jpg/960px-Fr_l%C3%A1zn%C4%9B_Soln%C3%BD_pramen.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:37','https://www.frantiskovy-lazne.info/cs/zajimava-mista/solny-pramen_298',0,'Františkovy Lázně',NULL,NULL),
(392,3,'pramen Stanislav','Lázeňský pramen ve Františkových lázních o hloubce (61 m), vznik v roce 1981. Uváděná vydatnost 120 l / min. Přístup: obec (zastavěné území).','SIGHTSEEING',15,50.12138600,12.35252800,'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/11/Franti%C5%A1kovy_L%C3%A1zn%C4%9B_pramen_Stanislav_z%C3%A1%C5%99%C3%AD_2022.jpg/960px-Franti%C5%A1kovy_L%C3%A1zn%C4%9B_pramen_Stanislav_z%C3%A1%C5%99%C3%AD_2022.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:38','https://www.frantiskovy-lazne.info/cs/zajimava-mista/pramen-stanislav_299',0,'Františkovy Lázně',NULL,NULL),
(393,3,'pramen Palliardi','Pramen se nachází při cestě vedoucí od Železnatého pramene zezadu ke kolonádě Solného a Lučního pramene. Osvěžující chutná kyselka. Používá se při nechutenství a lehkých katarech žaludečních. Přístup: pěšina (pěšky).','SIGHTSEEING',15,50.11403900,12.35671800,'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/12/Pramen_palliardi_2022-04-16_1.jpg/960px-Pramen_palliardi_2022-04-16_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:39','https://www.frantiskovy-lazne.info/cs/zajimava-mista/pramen-palliardi_296',0,'Františkovy Lázně',NULL,NULL),
(394,3,'pramen Žofie','K prameni se dostaneme buď po dřevěném chodníku vedoucím skrz podmáčený les od pramene Natálie, nebo po louce od ulice Pod Lipami. Vyvěrá asi půl metru pod úrovní země, voda je v porovnání s ostatními místními prameny málo mineralizovaná, uhličitá, příjemné chuti. Přístup: pěšina (pěšky).','SIGHTSEEING',15,50.11312100,12.36986200,'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/Franti%C5%A1kovy_L%C3%A1zn%C4%9B_pramen_%C5%BDofie_%283%29.jpg/960px-Franti%C5%A1kovy_L%C3%A1zn%C4%9B_pramen_%C5%BDofie_%283%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:40','https://www.frantiskovy-lazne.info/cs/zajimava-mista/pramen-zofie_302',0,'Františkovy Lázně',NULL,NULL),
(395,3,'Glauberův pramen (Glauber II)','V dřevěném altánu v Lesoparku Amerika se nachází pramen č.6 - Glauber II. Jímán formou vrtu, určený k pitné kúře. Je pramenem mírně projímavým, příjemné chuti. Osvědčuje se při katarech střevních a žaludečních. Má podobné, ale slabší účinky jako Glauber I. Přístup: pěšina (pěšky).','SIGHTSEEING',15,50.11808000,12.33965900,'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bf/Franti%C5%A1kovy_L%C3%A1zn%C4%9B_Glauber_II.jpg/960px-Franti%C5%A1kovy_L%C3%A1zn%C4%9B_Glauber_II.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:41','https://www.frantiskovy-lazne.info/cs/zajimava-mista/glauber-ii_286',0,'Františkovy Lázně',NULL,NULL),
(396,3,'Glauberův pramen (Glauber III)','V nejpompéznějším přístřešku, které prameny ve Františkových Lázních mají, vyvěrá pramen Glauber III. Tedy není to jen obyčejný přístřešek, ale Dvorana Glauberových pramenů, která byla vystavěná podle projektu františkolázeňského stavitele Ernsta Engelhardta a otevřená již roku 1930. Vedle pramene Glauber III tam naleznete také pramen Nový Kostelní a Glauber IV. Minerální voda z pramene Glauber III je k dispozici nejen uvnitř dvorany, ale také ve volně přístupném venkovním výtoku v pravé zadní části Glauberovy dvorany. Glauber III je jímán formou vrtu. Přístup: obec (zastavěné území).','SIGHTSEEING',15,50.11594200,12.35173700,'https://www.frantiskovy-lazne.info/files/franlaz-item/0/287/franlaz-item_287_img_16111336266180.jpg','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:42','https://www.frantiskovy-lazne.info/cs/zajimava-mista/glauber-iii_287',0,'Františkovy Lázně',NULL,NULL),
(398,3,'Luční pramen','Vyvěrá na jihozápadním konci empírové kolonády z roku 1844. Přístupný zdarma v denní dobu. Přístup: obec (zastavěné území).','SIGHTSEEING',15,50.11503000,12.35545000,'https://www.frantiskovy-lazne.info/files/franlaz-item/0/291/franlaz-item_291_img_16188443683833.JPEG','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:44','https://www.frantiskovy-lazne.info/cs/zajimava-mista/lucni-pramen_291',0,'Františkovy Lázně',NULL,NULL),
(399,3,'Nový Kostelní pramen','Vyvěrá ve Dvoraně Glauberových pramenů spolu s Glauber III a IV. Přístupný v denní dobu, odběr je možný zdarma z kohoutků a to jak studené, tak i ohřáté vody. Vydatnost: 56,4 l/min Teplota: 11,9 ºC Volný CO2: 1500 mg/l Odparek: 5413 mg/l HCO3: 1135 mg/l ph: 6,11 Vznik: 2000 Hloubka: 63 m. Přístup: obec (zastavěné území).','SIGHTSEEING',15,50.11583300,12.35175000,'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/Franti%C5%A1kovy_L%C3%A1zn%C4%9B_Nov%C3%BD_pramen_z%C3%A1%C5%99%C3%AD_2024.jpg/960px-Franti%C5%A1kovy_L%C3%A1zn%C4%9B_Nov%C3%BD_pramen_z%C3%A1%C5%99%C3%AD_2024.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:45','https://www.frantiskovy-lazne.info/cs/zajimava-mista/pramen-novy-kostelni_295',0,'Františkovy Lázně',NULL,NULL),
(400,3,'pramen Natálie','Pramen vytéká ze stěny rozměrného pavilónu Natálie, ke kterému se dostaneme buď příjemnou vycházkovou cestou od Železnatého pramene, nebo po cestě odbočující z ulice Pod Lipami (odevšad značeno). Čerpán je plošným zvonkovým jímáním a je určen k pitné kúře. Předepisuje se při chorobách ledvin a měchýře. Je velmi oblíbený pro svoji příjemnou a osvěžující chuť. Přístup: cesta (kolo).','SIGHTSEEING',15,50.11226600,12.36645100,'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d3/Franti%C5%A1kovy_L%C3%A1zn%C4%9B_pavilon_s_pramenem_Nat%C3%A1lie_%283%29.jpg/960px-Franti%C5%A1kovy_L%C3%A1zn%C4%9B_pavilon_s_pramenem_Nat%C3%A1lie_%283%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:46','https://www.frantiskovy-lazne.info/cs/zajimava-mista/pramen-natalie_293',0,'Františkovy Lázně',NULL,NULL),
(402,3,'Sluneční pramen','Sluneční pramen vyvěrá z hloubky 40 metrů. Nachází se v lázeňském parku nedaleko Labutího jezírka, má teplotu 10 °C a je bohatý na oxid uhličitý. Používá se při léčbě zažívacího ústrojů. Přístup: pěšina (pěšky).','SIGHTSEEING',15,50.12000900,12.34335300,'https://www.frantiskovy-lazne.info/files/franlaz-item/0/297/franlaz-item_297_img_16305195439942.JPEG','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:48','https://www.frantiskovy-lazne.info/cs/zajimava-mista/slunecni-pramen_297',0,'Františkovy Lázně',NULL,NULL),
(403,3,'pramen František','Nejznámnější pramen Františkových lázní je jímán v pavilonu, přístupné 8-18 hod, volný odběr. Vydatnost: 13,6 l/min Teplota: 11,4 ºC Volný CO2: 756 mg/l Odparek: 1359 mg/l HCO3: 433 mg/l ph: 5,8 Vznik: 1793 Hloubka: 6,2. Přístup: obec (zastavěné území).','SIGHTSEEING',15,50.11726000,12.35070300,'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/81/Franti%C5%A1kovy_L%C3%A1zn%C4%9B_pramen_Franti%C5%A1ek_%281%29.jpg/960px-Franti%C5%A1kovy_L%C3%A1zn%C4%9B_pramen_Franti%C5%A1ek_%281%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:49','https://www.frantiskovy-lazne.info/cs/zajimava-mista/pramen-frantisek_284',0,'Františkovy Lázně',NULL,NULL),
(404,31,'pramen Tereza','V současné době již po rekonstrukci, veden do dutého kmene. Přístup: pěšina (pěšky).','SIGHTSEEING',15,49.99842400,12.63649700,'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/L%C3%A1zn%C4%9B_Kyn%C5%BEvart_pramen_Tereza_duben_2019_%284%29.jpg/960px-L%C3%A1zn%C4%9B_Kyn%C5%BEvart_pramen_Tereza_duben_2019_%284%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:50','https://www.estudanky.eu/8470',0,'Lázně Kynžvart',NULL,NULL),
(405,31,'pramen Helena a Viktor','Voda silně mineralizovaná, je pouze ochutnavatelná. V případě větší konzumace by mohly hrozit střevní potíže. Přístup: obec (zastavěné území).','SIGHTSEEING',15,50.00825300,12.63205800,'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/52/HelenaaViktor.jpg/960px-HelenaaViktor.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:51','https://www.lazne-kynzvart.cz/cs/lazenska-pece/prirodni-lecive-zdroje',0,'Lázně Kynžvart',NULL,NULL),
(406,31,'pramen Richard','Pramen Richard v Kynžvartě je volně přístupný minerální pramen s historií sahající až do 15. století. Pojmenován po Richardu Metternichovi, významném pro rozvoj lázeňství, vyvěrá v nadmořské výšce 704 m. Voda je podobná pramenům z Mariánských Lázní, bohatá na oxid uhličitý a s nízkým obsahem železa, díky čemuž má vysokou trvanlivost. Odběr minerální vody z pavilonu je zpoplatněn, pramen spravuje Dětská léčebna Lázně Kynžvart a využívá se pro léčbu pacientů. Přístup: obec (zastavěné území).','SIGHTSEEING',15,50.00746400,12.63396000,'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/88/L%C3%A1zn%C4%9B_Kyn%C5%BEvart_pramen_Richard_%281%29.jpg/960px-L%C3%A1zn%C4%9B_Kyn%C5%BEvart_pramen_Richard_%281%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:52','https://www.lazne-kynzvart.cz/cs/o-nas/kyselka-richard',0,'Lázně Kynžvart',NULL,NULL),
(407,35,'pramen Marie Z','Vývěrá na čele staré meliorační rýhy kolmé k hlavnímu toku. Má úctyhodnou aktivitu 4.3 - 5.8 kBq/l 222Rn při průtoku 1-2 l/min. Radioaktivnější je překvapivě při vyšších průtocích. Radioaktivní jsou i nedaleké dva vývěry tvořící počátek potůčku v uzávěru údolí. Tento pramen má však zdaleka nejvyšší průtok. Nazvali ho \"Marie Z\" na počest RNDr. Marie Zukriegelové, CSc. (1926-2010), radioložky Českého geologického ústavu, která popsaný klastr tří radioaktivních pramenů objevila na konci 50. let 20. století. Pramen byl podchycen a výtok obložen kamennou zídkou. Přístup: volný terén.','SIGHTSEEING',15,50.18483500,12.35823100,'https://www.estudanky.eu/foto8/10850.jpg','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:53','https://www.estudanky.eu/10850',0,'Skalná',NULL,NULL),
(408,75,'pramen Šabinská kyselka','Šabinská kyselka je jednou z mnoha, které vyvěrají z rašelin, jižně od obce Šabina. Minerálka je příjemně nakyslé chuti o teplotě cca 9°C. Vydatnost zdroje je přibližne 1 litr za minutu. Minerálka se vyznačuje vyšším obsahem železa a přítomností kyseliny uhličité, sírové a křemičité. Svým složením se podobá známým minerálním vodám Mattoni a Korunní. Přístup: cesta (kolo).','SIGHTSEEING',15,50.12864600,12.58425700,'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7d/%C5%A0abinsk%C3%A1_kyselka_j%C3%ADm%C3%A1n%C3%AD_%C4%8Dervenec_2019_%283%29.jpg/960px-%C5%A0abinsk%C3%A1_kyselka_j%C3%ADm%C3%A1n%C3%AD_%C4%8Dervenec_2019_%283%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:54','https://www.estudanky.eu/357',0,'Šabina',NULL,NULL),
(409,76,'pramen U cesty','Dobrý pitný zdroj. Přístup: silnice (autem).','SIGHTSEEING',15,50.36238300,12.54150900,'https://www.estudanky.eu/foto1/413.jpg','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:55','https://www.estudanky.eu/413',0,'Stříbrná',NULL,NULL),
(410,62,'Fridrichův pramen','Pramen u osady Brtná u Dolního Žandova. Podle Průvodce po minerálních pramenech Českého lesa jde o železnatou hydrogenuhličitanovou hořečnato-sodnou kyselku s obsahem CO2 2660 mg/l. Přístup: volný terén.','SIGHTSEEING',15,50.01226000,12.52915900,'https://www.estudanky.eu/foto1/499.jpg','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:56','https://www.estudanky.eu/499',0,'Dolní Žandov',NULL,NULL),
(411,62,'pramen Radiovka','Místní nazývají tento prostor jako „Kňafák“. Radioaktivní minerální pramen se dříve stáčel do lahví a používal se pro léčivé účely. Své jméno získal díky vysokému obsahu přírodní radioaktivity. V místě se nacházejí dva vývěry: hlavní Radiovka a boční méně nasycený Nektar. Přístup: cesta (kolo).','SIGHTSEEING',15,50.05001400,12.56551400,'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Podles%C3%AD_pramen_Radionka.jpg/960px-Podles%C3%AD_pramen_Radionka.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:57','https://www.estudanky.eu/502',0,'Dolní Žandov',NULL,NULL),
(412,29,'minerální pramen Doubrava','Minerální pramen umístěný cca uprostřed obce Doubrava. K pramenu je potřeba vejít do upraveného domečku, v úrovni horní podlahy domečku je kohoutek s tlačítky. Přístup: silnice (autem).','SIGHTSEEING',15,50.26060300,12.23969800,'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4c/Kyselka_v_Doubrav%C4%9B_pavilon_%281%29.jpg/960px-Kyselka_v_Doubrav%C4%9B_pavilon_%281%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:58','https://www.estudanky.eu/1584',0,'Aš',NULL,NULL),
(413,29,'minerální pramen Dolní paseky','Minerální pramen v Dolních Pasekách byl zmiňován již ve 12. století. Později v 16. století ho považovali za léčebný. V roce 1870 ho ašský továrník Gustav Geipel nechal testovat a postavil u něho dřevěný altán. Altán byl v roce 1930 přestavěn na zděný pavilon. Přístup: silnice (autem).','SIGHTSEEING',15,50.23597500,12.23594800,'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/04/Kyselka_v_Doln%C3%ADch_Pasek%C3%A1ch_%282%29.jpg/960px-Kyselka_v_Doln%C3%ADch_Pasek%C3%A1ch_%282%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:59','https://www.estudanky.eu/1585',0,'Aš',NULL,NULL),
(414,67,'Ottův pramen','Ottův pramen je jeden ze dvou minerálních zásaditých pramenů v obci Kyselka na Karlovarsku. Současný vývěr pochází z vrtu Ottova pramene. Původní pramen byl pojmenován na počest návštěvy řeckého krále Otty (1815–1867), který v roce 1852 lázně Kyselka navštívil. Jeho vody byly stáčeny Heinrichem Mattonim (1830–1910). Nad původním místem vývěru byla postavena Ottova kolonáda. Přístup: silnice (autem).','SIGHTSEEING',15,50.25900600,12.99909600,'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/90/Kyselka_%28078%29.jpg/960px-Kyselka_%28078%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:60','https://www.estudanky.eu/1901',0,'Kyselka',NULL,NULL),
(415,67,'Jindřichův pramen','Jindřichův pramen je pojmenován podle Heinricha (Jindřicha) Mattoniho a vede k němu krátká odbočka z červené turistické trasy pod silnicí mezi Kyselkou a Radošovem. Vývěr pramene je situován v malém domečku. Na rozdíl od Ottova pramene, s nímž sdílí podobné chemické složení, obsahuje méně CO2 a má nižší mineralizaci. Přístup: obec (zastavěné území).','SIGHTSEEING',15,50.26852900,12.99405200,'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dd/Jind%C5%99ich%C5%AFv_pramen.jpg/960px-Jind%C5%99ich%C5%AFv_pramen.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:61','https://www.estudanky.eu/2245',0,'Kyselka',NULL,NULL),
(416,36,'pramen Křepkovická kyselka','Kyselka se nachází jižně od obce Křepkovice na kraji lesa po levé straně silnice směrem na Hanov. Její obnova proběhla v roce 2010. Je zatím nejstarším doloženým, kontinuálně využívaným minerálním pramenem v Tepelské vrchovině a jedním z nejstarších v Karlovarském kraji vůbec. Přístup: silnice (autem).','SIGHTSEEING',15,49.93202600,12.87794000,'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ea/K%C5%99epkovick%C3%A1_kyselka_%C4%8Derven_2023_%281%29.jpg/960px-K%C5%99epkovick%C3%A1_kyselka_%C4%8Derven_2023_%281%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:62','https://www.estudanky.eu/3633',0,'Teplá',NULL,NULL),
(417,33,'Srnčí pramen','K prameni vede špatně značená a neschůdná cesta z Aleje svobody (modrá značka). Pramen je v letních měsících skryt ve vegetaci, takže je snadné ho přehlédnout. Přístup: pěšina (pěšky).','SIGHTSEEING',15,49.98123800,12.68164900,'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/46/Srn%C4%8D%C3%AD_pramen.jpg/960px-Srn%C4%8D%C3%AD_pramen.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:63','https://www.estudanky.eu/3698',0,'Mariánské Lázně',NULL,NULL),
(418,77,'Janovského pramen','Pramen v zaniklé obci Slatina - Lohhäuser. Janský byl fořt a čestný občan obce Lohhäuser. Zdroj uvádí, že voda není pitná. Přístup: cesta (kolo).','SIGHTSEEING',15,49.93369400,12.53424600,'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/11/Slatina_Janovsk%C3%A9ho_pramen_kv%C4%9Bten_2020_%281%29.jpg/960px-Slatina_Janovsk%C3%A9ho_pramen_kv%C4%9Bten_2020_%281%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:64','https://www.estudanky.eu/4180',0,'Stará Voda',NULL,NULL),
(420,53,'pramen Svatovítská kyselka','Kyselka vyvěrá na levém břehu Senného potoka pod hrází rybníka v bývalém vojenském prostoru. Okolo roku 1925 byla zachycena do šestnáctisegmentového dřevěného pažení. Přístup: pěšina (pěšky).','SIGHTSEEING',15,49.92966100,12.63663300,'https://www.estudanky.eu/foto4/5058.jpg','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:66','https://www.estudanky.eu/5058',0,'Trstěnice',NULL,NULL),
(421,24,'pramen U čistého potoka','Tento pramen se nachází cca 3km západně od Horního Slavkova, na okraji podmáčené nivní louky v prostoru mezi soutokem Komářího (Čistého) potoka a potoka od Třídomí. Zdroj je podchycen v malé skruži opatřené dřevěným poklopem a slouží jako zdroj pitné vody pro přilehlou chatovou osadu \"Čistý potok\", od které je k němu přístup přes podmáčenou louku usnadněn po dřevěných latích. Přístup: volný terén.','SIGHTSEEING',15,50.14247100,12.75898400,'https://www.estudanky.eu/foto4/5489.jpg','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:67','https://www.estudanky.eu/5489',0,'Loket',NULL,NULL),
(422,34,'pramen Plesenská kyselka','Upravený zdroj, hojně navštěvovaný, kam si jezdí lidé s lahvemi pro chutnou, mírně nakyslou minerální vodu. Přístup: pěšina (pěšky).','SIGHTSEEING',15,50.22770600,12.36463900,'https://www.estudanky.eu/foto4/5786.jpg','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:68','https://www.estudanky.eu/5786',0,'Plesná',NULL,NULL),
(423,34,'pramen Za školou','Vydatný pramen příjemně nakyslé, studené, železité minerálky, pro kterou si chodí lidé s lahvemi. Přístup: volný terén.','SIGHTSEEING',15,50.22503400,12.34950800,'https://www.estudanky.eu/foto4/5814.jpg','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:69','https://www.estudanky.eu/5814',0,'Plesná',NULL,NULL),
(424,77,'pramen Kosí (Kosový) potok','Kosí (Kosový) potok pramení v sedle mezi Dylení a Čupřinou v místech, kam se dřív nesmělo. Najít pramen je poněkud namáhavé, nutno projít přírodním lesem. Voda ve vývěru zpod kořenů smrkového pařezu je konzumovatelná. Přístup: volný terén.','SIGHTSEEING',15,49.96356500,12.50241600,'https://www.estudanky.eu/foto4/5942.jpg','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:70','https://www.estudanky.eu/5942',0,'Stará Voda',NULL,NULL),
(425,33,'Myší pramen','Vývěr je v původním kmeni, zastřešený, v letních měsících osvěžující. Cesta je značena od viaduktu a je schůdná. Přístup: pěšina (pěšky).','SIGHTSEEING',15,49.97684100,12.67280600,'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/26/My%C5%A1%C3%AD_kyselka.jpg/960px-My%C5%A1%C3%AD_kyselka.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:71','https://www.estudanky.eu/7057',0,'Mariánské Lázně',NULL,NULL),
(426,79,'Barochův pramen','V některých záznamech veden jako Obecní. Pramen i s přístupovou cestou byl opraven v rámci projektu Živé studánky. Od autobusové zastávky Prameny, křižovatka, k němu vede pohodlná a dobře označená pěšina. Jedná se o slabě mineralizovaný, uhličitý, železitý pramen. Přístup: pěšina (pěšky).','SIGHTSEEING',15,50.04711400,12.72820400,'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c0/Baroch%C5%AFv_pramen_%C4%8Derven_2019_%282%29.jpg/960px-Baroch%C5%AFv_pramen_%C4%8Derven_2019_%282%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:72','https://www.estudanky.eu/7280',0,'Prameny',NULL,NULL),
(427,79,'Giselin a Rudolfův pramen','Giselin a Rudolfův pramen se nachází za obcí Prameny po levé straně silnice směrem na Kladskou. Prameny jsou od sebe vzdáleny asi 4 metry a jejich voda je svedena do jednoho odběrného místa, Zachycení pramenů je efektní a provedené tradičně do dřevěného obložení, prameny vyvěrají v místě bývalého parku před zničenými lázněmi v Pramenech. Vody pramenů silně probublává oxid uhličitý. Přístup: pěšina (pěšky).','SIGHTSEEING',15,50.04557900,12.72451300,'https://www.estudanky.eu/foto5/7282.jpg','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:73','https://www.estudanky.eu/7282',0,'Prameny',NULL,NULL),
(428,43,'pramen Žebrácká studánka','Nachází se za obcí Jindřichovice (v Krušných horách), cca 270 m jihozápadně od kostela sv. Martina, ve svahu nad levým břehem potoka (cca 25 m od břehu potoka), který teče z Jindřichovic ZJZ směrem. Přístup: volný terén.','SIGHTSEEING',15,50.28043500,12.60055200,'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f9/Jind%C5%99ichovice_stud%C3%A1nka.jpg/960px-Jind%C5%99ichovice_stud%C3%A1nka.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:74','https://www.estudanky.eu/8091',0,'Jindřichovice',NULL,NULL),
(430,80,'pramen U Hubertusu','Pramen je využíván jako zdroj pitné vody pro nedaleké vodácké tábořiště.O cca 10 metru dále od prameniště po proudu řeky se nachází další proud pramene, nyní již zarostlý. O pramen jednou za čas pečují místní chataři, případně pokud už studánka hodně teče tak správce tábořiště. Jedná se o jediný veřejný zdroj pitné vody v okolí druhého břehu Ohře v okruhu cca 5km. Nedaleká osada ani tábořiště není z důvodu složitého terénu připojeno na rozvod pitné vody, dvě neveřejné studny v osadě jsou kontaminované a nepitné. Přístup: pěšina (pěšky).','SIGHTSEEING',15,50.24193800,12.92601900,'https://www.estudanky.eu/foto6/8304.jpg','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:76','https://www.estudanky.eu/8304',0,'Sadov',NULL,NULL),
(432,45,'pramen U Vojkovic','Příjemné osvěžení na turistické trase z Vojkovic dále po proudu Ohře. Přístup: obec (zastavěné území).','SIGHTSEEING',15,50.28825000,13.00700000,'https://www.estudanky.eu/foto7/10023.jpg','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:78','https://www.estudanky.eu/10023',0,'Velichov',NULL,NULL),
(433,35,'pramen Pod Skalou','Pramen Pod Skalou je dalším blahodárným zdrojem radioaktivní minerální vody na území budovaném na uran mimořádně fertilním smrčinským granitem. Tento minerální pramen byl nevědomky zachycen v mladší (západní) větvi skalenského vodovodu pod Novým Světem. Vodovodní jímání projektovala v roce 1921 firma G. Rumpel z Teplic a realizovala v roce 1923 firma Rudolf Braun z Plané. Při stavbě obou větví vodovodu byl zachycen větší počet radioaktivních vývěrů, pramen Pod Skalou má z nich aktivitu nejvyšší. Obě větve \"radioaktivního skalenského vodovodu\" byly na počátku 80. let 20. stol. pro nedostačující výkon odpojeny. Dnes je Skalná zásobována pitnou vodou s nízkou aktivitou z dálkového vodovou. Pramen Pod Skalou je vyvedený z jedné ze záchytných jímek a vytéká přirozeným tlakem na povrch. Nazván byl podle dramatické žulové ostrožny, pod níž vyvěrá. Technická úprava byla dokončena v září 2018. Pramen je pozorován až od roku 2017, s naměřenou aktivitou 5.2 - 8 kBq/l 222Rn a průtokem okolo 1.5 l/min. Vodu je možno užívat k léčivým účelům. Platí stejné zásady jako u ostatních druhů minerálních vod: Voda se nehodí pro trvalou spotřebu, jednorázová konzumace může mít nanejvýše mírné tonizační účinky. Přístup: volný terén.','SIGHTSEEING',15,50.17395000,12.34984500,'https://www.estudanky.eu/foto9/12362.jpg','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:79','https://www.estudanky.eu/12362',0,'Skalná',NULL,NULL),
(434,62,'pramen Obecní kyselka (Salajna)','Znovuobjevený minerální pramen v Salajně. Původně vyvěral v mělkém dutém kmenu, na který se narazilo při úpravác chodníčku v hloubce 1,2 m. Kyselka byla zaniklá nejméně 100 let. Využívána pravděpodobně již v 15. století. Dnes dobře přístupná a chutná. Přístup: obec (zastavěné území).','SIGHTSEEING',15,50.02334100,12.51729900,'https://www.estudanky.eu/foto9/13338.jpg','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:80','https://www.estudanky.eu/13338',0,'Dolní Žandov',NULL,NULL),
(435,34,'pramen Velebil','Divoký vývěr kyselky v údolí Pstruhového potoka. Tento silný pramen vyvěrá asi 10 m od potoka, na jeho levém břehu, v bažinaté nivě. Má průtok 3-15 l/min, obsah rozpuštěného CO2 v rozmezí 1506-1630 mg/l, celkovou mineralizaci 236 mg/l. Voda je chemického typu Fe-Mg-HCO3-SO4. Železo, jehož kyselka obsahuje neobvykle mnoho, 31.5 mg/l, se sráží všude kolem vývěru i odtoku do potoka v podobě mohutných spoust rezavého okru. Voda je studená a chutná, klasická \"plnotučná\" železitá kyselka. Vlastní pramen má podobu širokého bublajícího vývařiště, k němuž lze proniknout jen s velkou opatrností, neboť se celé okolí doslova \"houpe pod nohama\" a jeho únosnost rychle klesá, jak se k prameni přibližujete. Právě poloha v rozsáhlé bažině a nízká niveleta od hladiny potoka byly nejspíše důvodem, že tento dlouho známý pramen kyselky nebyl nikdy podchycen a nachází se unikátně ve zcela přírodním stavu, bez zásahu lidské ruky. Takových míst je dnes již málo. Lokalita je bez holin v podstatě nedostupná. Přístup: volný terén.','SIGHTSEEING',15,50.23477000,12.36927200,'https://www.estudanky.eu/foto10/13915.jpg','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:81','https://www.estudanky.eu/13915',0,'Plesná',NULL,NULL),
(436,33,'Velesův pramen','Studánka funguje, je schovaná v lese, což také také znamená, že se trochu špatně hledá. Voda je studená a skvěle chutná. Přístup: pěšina (pěšky).','SIGHTSEEING',15,49.96688600,12.72473100,'https://www.estudanky.eu/foto10/14411.jpg','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:82','https://www.estudanky.eu/14411',0,'Mariánské Lázně',NULL,NULL),
(439,40,'pramen Výhledská studánka','Studánka byla zapomenuta a ponechána svému osudu, obnovena byla v roce 2024, aktuální stav není znám. Přístup: cesta (kolo).','SIGHTSEEING',15,50.19311800,12.26440100,'https://www.estudanky.eu/foto11/15285.jpg','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:85','https://www.estudanky.eu/15285',0,'Hazlov',NULL,NULL),
(440,59,'pramen Korunní kyselka','Pramen vyvěrá u vsi Korunní poblíž obce Stráž nad Ohří. Vzniká několik desítek metrů pod povrchem v oblasti Doupovských hor, nedaleko Karlových Varů.','SIGHTSEEING',15,50.34140100,13.06764000,'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e1/Korunn%C3%AD_kyselka_%281%29.jpg/960px-Korunn%C3%AD_kyselka_%281%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'PRAMEN,ATRAKCE',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:86','https://www.estudanky.eu/405',0,'Stráž nad Ohří',NULL,NULL),
(441,84,'Grünská kyselka','Grünská kyselka je dalším z oblíbených výletních míst minulosti. Nachází ze nedaleko Novoveské kyselky v lese kousek od silnice mezi obcemi Nová Ves a Louka. Narozdíl od Novoveské kyselky se zde můžete osvěžit znamenitým minerálním pramenem, který je kryt altánem. Poblíž je vrt, ze kterého se jímá minerální voda prodávající se pod označením Magnesia. Přístup: silnice (autem).','SIGHTSEEING',15,50.06667000,12.78805600,'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/22/Gr%C3%BCnsk%C3%A1_kyselka_%C4%8Dervenec_2018_%281%29.jpg/960px-Gr%C3%BCnsk%C3%A1_kyselka_%C4%8Dervenec_2018_%281%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:87','https://www.estudanky.eu/2235',0,'Nová Ves',NULL,NULL),
(442,77,'Kyselka v Jedlové (studánka Jedlová)','Vývěr minerálního pramene se nachází na levém břehu Kosího potoka. Pramen v minulosti stříkal přerušovaně (intermitoval), což bývá způsobené existencí podzemní dutiny. Ta se určitou dobu plní, a poté minerální voda vytryskne. V roce 1974 byl interval mezi vytrysknutími 9 - 20 vteřin, dnes již tento jev zanikl. Voda obsahuje oxid uhličitý (přes 3 000 mg v litru) a látky s podílem iontů sodíku, hořčíku a vápníku. Oproti jiným kyselkám má méně železa. Teplota vody pramene je kolem +7,2 °C a ph má hodnotu 5,5. Kvalita vody není sledována, a proto je pití na vlastní nebezpečí. Přístup: cesta (kolo).','SIGHTSEEING',15,49.97355100,12.58884400,'https://commons.wikimedia.org/wiki/Special:FilePath/Jedlovsk%C3%A1%20kyselka%20%C4%8Dervenec%202019%20%282%29.jpg?width=800','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:88','https://www.estudanky.eu/2555',0,'Stará Voda',NULL,NULL),
(443,33,'Koňský pramen','Koňský pramen je nejvýznamnějším ze tří vývěrů historicky uváděných v údolí Chotěnovského potoka, který se pod Chotěnovem vlévá do Kosího (Kosového) potoka. Jeho jméno vzniklo podle pověsti, podle které se za třicetileté války zde v bažine utopilo koňské spřežení. Jedná se o přírodní památku, nachází se nad obcí Chotěnov v CHKO Slavkovský les. Jedná se o vývěr přírodní uhličité kyselky s převážně hořečnato–železnatým složením. Přístup: pěšina (pěšky).','SIGHTSEEING',15,49.93285600,12.73862600,'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0c/P%C5%99%C3%ADrodn%C3%AD_pam%C3%A1tka_Ko%C5%88sk%C3%BD_pramen_%281%29.jpg/960px-P%C5%99%C3%ADrodn%C3%AD_pam%C3%A1tka_Ko%C5%88sk%C3%BD_pramen_%281%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:89','https://www.estudanky.eu/1938',0,'Mariánské Lázně',NULL,NULL),
(444,56,'Kopaninská kyselka','Kopaninská kyselka je volně přístupný minerální pramen v přírodním parku Leopoldovy Hamry, nedaleko obce Nový Kostel. Vzniká na úpatí Krušných hor a je známá svou kyselou chutí s inkoustovými tóny a vysokým obsahem oxidu uhličitého. Pramen byl v roce 2018 zrekonstruován a zpřístupněn s novým přístřeškem a povalovým chodníkem. Ideální zastávka pro milovníky přírody a léčivých vod. Přístup: pěšina (pěšky).','SIGHTSEEING',15,50.20584700,12.45763900,'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c5/Kopanina_miner%C3%A1ln%C3%AD_pramen_%281%29.jpg/960px-Kopanina_miner%C3%A1ln%C3%AD_pramen_%281%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:90','https://cs.wikipedia.org/wiki/Kopaninsk%C3%A1_kyselka',0,'Nový Kostel',NULL,NULL),
(445,71,'Kyselecký pramen (hamr)','Chutný, vydatný pramen s dlouhou tradicí. Osvěžující minerálka pro všechny kolemjdoucí. Přístup: pěšina (pěšky).','SIGHTSEEING',15,50.00156700,12.46483100,'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bf/Miner%C3%A1ln%C3%AD_pramen_Kyseleck%C3%BD_hamr_%281%29.jpg/960px-Miner%C3%A1ln%C3%AD_pramen_Kyseleck%C3%BD_hamr_%281%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:91','https://www.estudanky.eu/4443',0,'Lipová',NULL,NULL),
(446,36,'kyselka Oriona','Kyselka Oriona u obce Jankovice. Před válkou byla přímo v obci stáčírna. Po roce 1945 nebylo stáčení obnoveno. Počátkem 80. let byla kyselka přivedena potrubím k silnici u Teplé a zde postaven malý přístřešek. Oriona je hojně využívaný a nejkvalitnější minerální pramen na Tepelsku. Nachází se u silnice za Teplou směrem na Mariánské Lázně. Studánka je kryta altánem a je u ní zřízeno odpočívadlo. Přístup: silnice (autem).','SIGHTSEEING',15,49.97384100,12.84169600,'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/46/Miner%C3%A1ln%C3%AD_pramen_Oriona_%C4%8Dervenec_2020_%281%29.jpg/960px-Miner%C3%A1ln%C3%AD_pramen_Oriona_%C4%8Dervenec_2020_%281%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:92','https://www.estudanky.eu/3218',0,'Teplá',NULL,NULL),
(447,85,'pramen Otročínská kyselka','Pramen otročínské kyselky je znám a využíván od sedmnáctého století, kdy se o něm zmiňuje Bohuslav Balbín. Vydatnost pramene je približně dva litry za minutu. Během podzimu roku 2008 proběhla úprava okolí s výstavbou nového altánku, ke kterému se dostaneme po modré turististické cestě z Otročína od obecního úradu. Přístup: pěšina (pěšky).','SIGHTSEEING',15,50.01815100,12.89233500,'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e8/Otro%C4%8D%C3%ADnsk%C3%A1_kyselka_%C4%8Derven_2023_%281%29.jpg/960px-Otro%C4%8D%C3%ADnsk%C3%A1_kyselka_%C4%8Derven_2023_%281%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:93','https://www.estudanky.eu/2228',0,'Otročín',NULL,NULL),
(448,23,'Pochlovická minerálka','U Pochlovické minerálky jsou dva prameny vedle sebe cca 4m. Název mají stejný. Přístup: pěšina (pěšky).','SIGHTSEEING',15,50.13194800,12.50748900,'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9d/Pochlovick%C3%A1_kyselka.jpg/960px-Pochlovick%C3%A1_kyselka.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:94','https://www.estudanky.eu/5135',0,'Kynšperk nad Ohří',NULL,NULL),
(449,86,'pramen Panská kyselka','Pramen byl dříve nazýván štolní nebo \"štolový\". Dnes je nazýván Panská kyselka, podle Panského vrchu, kde se nachází. Někdy je označován jako Drmoul I. Archeologicky je doložena existence pramene již ve druhé polovině 14. století. Je to jeden z nejdéle kontinuálně využívaných pramenů na Mariánskolázeňsku. Přístup: pěšina (pěšky).','SIGHTSEEING',15,49.94351800,12.64554000,'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/43/Pansk%C3%A1_kyselka_z%C3%A1%C5%99%C3%AD_2019_%281%29.jpg/960px-Pansk%C3%A1_kyselka_z%C3%A1%C5%99%C3%AD_2019_%281%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:95','https://www.estudanky.eu/3492',0,'Drmoul',NULL,NULL),
(450,33,'pramen Taormína','Nejlepší přístup ke studánce je po chodníku odbočujícím nahoru z ulice Anglická několik metrů od jižnější spojky s ulicí Zeyerovou. Tento chodník vás dovede téměř až ke studánce, nemůžete ji minout. Nejedná se o minerálku, nýbrž o prostou vodu. Přístup: obec (zastavěné území).','SIGHTSEEING',15,49.96500200,12.70812200,'https://www.estudanky.eu/foto6/8015.jpg','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:96','https://www.estudanky.eu/8015',0,'Mariánské Lázně',NULL,NULL),
(451,79,'Nový pramen','Asi 40 m pod známějšími a pěkně upravenými prameny Gisela a Rudolf najdeme ještě jeden, Nový pramen (jiný název Prutovka). Od Giselina a Rudolfova pramene vede buďto pěšinka kolmo k silnici, nebo šikmo směrem do Pramenů. Vydáme-li se po pěšině k vesnici, po pravé straně z ní odbočuje k potoku. Přeskočíme potok a za ním najdeme pramen. Je jednoduše upraven, vlastně se jedná jen o trubku obloženou několika kameny, ale zachycení funguje a pramen dobře teče. Jedná se o slabě mineralizovanou, uhličitou, železitou kyselku příjemné chuti. Přístup: pěšina (pěšky).','SIGHTSEEING',15,50.04575300,12.72515100,'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/de/Prameny_Nov%C3%BD_pramen_b%C5%99ezen_2024.jpg/960px-Prameny_Nov%C3%BD_pramen_b%C5%99ezen_2024.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:97','https://www.estudanky.eu/12839',0,'Prameny',NULL,NULL),
(452,67,'pramen Dubina','Pramen se nachází přímo u zastávky autobusu, naproti hostinci Dubina. Vzhledem k tomu, že cca o 2 km dále se nachází známý pramen Mattoni, tento je prakticky neznámý. Přístup: silnice (autem).','SIGHTSEEING',15,50.24384900,12.99190300,'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a8/Dubina_%28%C5%A0emnice%29%2C_most.jpg/960px-Dubina_%28%C5%A0emnice%29%2C_most.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:98','https://www.estudanky.eu/12920',0,'Kyselka',NULL,NULL),
(453,74,'pramen Lesopark Pernink','Pramen v lesoparku Pernink byl obnoven jako součást revitalizace. Voda vytéká z plastové trubky nad kamenným žlabem. Okolní prostor je vydlážděn kameny. S lesoparkem seznamuje naučná stezka Lesopark Pernink, která má u pramene zastavení č. 4. Přístup: cesta (kolo).','SIGHTSEEING',15,50.36498400,12.78159700,'https://www.estudanky.eu/foto10/14965.jpg','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:99','https://www.estudanky.eu/14965',0,'Pernink',NULL,NULL),
(454,36,'studánka Helenka - Hoštecká (Thürmerova) kyselka','Hoštecká (Thürmerova) kyselka je uhličitá železnatá kyselka. Jímání pramene bylo opraveno v roce 2021. Přístup: pěšina (pěšky).','SIGHTSEEING',15,49.98850000,12.82744400,'https://www.estudanky.eu/foto11/15050.jpg','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:100','https://www.estudanky.eu/15050',0,'Teplá',NULL,NULL),
(456,56,'studánka Mlýnská kyselka','Dříve nazýváno Grüne Mühle. Před II. světovou válkou slavné lázně. Voda z pramene balena do lahve pro potřeby vojáků bojujících v pouštních oblastech severní Afriky. Po odsunu německých občanů místo nazýváno U Priského (dle obyvatele, který bydlel ve vile u pramene). Za komunistů v 80 letech pramen zcela zničen. Po cca 30 letech obnoven obcí Křižovatka. Přístup: pěšina (pěšky).','SIGHTSEEING',15,50.18333700,12.42833300,'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5c/Ml%C3%BDnsk%C3%A1_kyselka_%C5%99%C3%ADjen_2020_%282%29.jpg/960px-Ml%C3%BDnsk%C3%A1_kyselka_%C5%99%C3%ADjen_2020_%282%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:102','https://www.estudanky.eu/11582',0,'Nový Kostel',NULL,NULL),
(457,83,'Kaffská studánka','Kaffská studánka je vývěr pramenité vody v bývalé vsi Dolní Kaff. Nedaleko informační tabule blízko rozvalinám, se nachází stará studánka v jakémsi sklípku. Voda je čistá a chutná. Nachází se na naučné stezce Merklín a je o ní zmínka na informační tabuli o dolním Kaffu. Přístup: cesta (kolo).','SIGHTSEEING',15,50.34162900,12.85244700,'https://www.estudanky.eu/foto9/13477.jpg','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:103','https://www.estudanky.eu/13477',0,'Merklín',NULL,NULL),
(458,87,'pramen Horka','Pramen Horka u Jilmového potoka nedaleko obce Martinov, jihovýchodně od Mariánských Lázní. Přístup: silnice (autem).','SIGHTSEEING',15,49.93925000,12.75896000,'https://www.estudanky.eu/foto2/2056.jpg','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:104','https://www.estudanky.eu/2056',0,'Vlkovice',NULL,NULL),
(459,1,'pramen Živá voda','Pramen najdete u rozcestí U chaty básníků nedaleko karlovarského mezinárodního letiště Olšová Vrata. Přístup: pěšina (pěšky).','SIGHTSEEING',15,50.20714600,12.89061600,'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2a/Karlovy_Vary_alt%C3%A1n_B%C3%A1sn%C3%ADk%C5%AF_6_%C5%BDiv%C3%A1_voda.jpg/960px-Karlovy_Vary_alt%C3%A1n_B%C3%A1sn%C3%ADk%C5%AF_6_%C5%BDiv%C3%A1_voda.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:105','https://www.estudanky.eu/3603',0,'Karlovy Vary',NULL,NULL),
(460,31,'Liščí prameny','Jedná se o dva v těsné blízkosti vedle sebe vyvěrající prameny (oba pod stejným názvem). Jímka je archeologicky datována do 17. století. Tyto prameny jsou pravděpodobně značeny již na Müllerově mapě z roku 1720. Prameny nejsou sledovány z hlediska hygienické nezávadnosti a konzumace je tudíž na vlastní nebezpečí. Přístup: pěšina (pěšky).','SIGHTSEEING',15,49.99901500,12.65389000,'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/be/Kyn%C5%BEvart_Li%C5%A1%C4%8D%C3%AD_prameny_%281%29.jpg/960px-Kyn%C5%BEvart_Li%C5%A1%C4%8D%C3%AD_prameny_%281%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:106','https://www.estudanky.eu/3609',0,'Lázně Kynžvart',NULL,NULL),
(461,31,'Kančí pramen','V roce 2004 náhodně v rašeliništi nalezený pramen zachycený do soudku. Pramen byl nalezen po 1,5m mocnou vrstvou rašeliny. Má vysoký obsah CO2 a je velmi osvěžujíci. Není sledován z hlediska hygienické kvality a tak je konzumace pouze na vlastní nebezpečí. Náleží ke skupině takzvaných Kynžvartských kyselek. Přístup: pěšina (pěšky).','SIGHTSEEING',15,49.99882600,12.65413100,'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/95/Kyn%C5%BEvart_Kan%C4%8D%C3%AD_pramen_%281%29.jpg/960px-Kyn%C5%BEvart_Kan%C4%8D%C3%AD_pramen_%281%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:107','https://www.estudanky.eu/3611',0,'Lázně Kynžvart',NULL,NULL),
(462,31,'Jezevčí pramen','Jedna ze skupiny Kynžvartských kyselek, jihovýchodně od města Kynžvartu. Vyvěrá do kameninové jímky ve tvaru osmistěnu. Odtéká z ní malý potůček s typicky vysráženým železem. Přístup: pěšina (pěšky).','SIGHTSEEING',15,50.00019000,12.64803900,'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d6/Kyn%C5%BEvart_Jezev%C4%8D%C3%AD_pramen_%281%29.jpg/960px-Kyn%C5%BEvart_Jezev%C4%8D%C3%AD_pramen_%281%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:108','https://www.estudanky.eu/3612',0,'Lázně Kynžvart',NULL,NULL),
(463,6,'Železitý pramen','Téměř zapomenutý pramen byl upraven a zpřístupněn v roce 2009. Přístup: silnice (autem).','SIGHTSEEING',15,50.14559500,13.03728200,'https://www.estudanky.eu/foto3/4308.jpg','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:109','https://www.estudanky.eu/4308',0,'Bochov',NULL,NULL),
(464,15,'pramen Studánka Podhoří','Poměrně silný pramen vyvěrá na severovýchodním svahu Třebouňského vrchu, při silnici z Třebouně do Bezděkova. Přírodní vývěr se nachází pod znětí padlých a živých stromů, přístup k němu usnadňuje dřevěná lávka přes silniční příkop. Na pramen upozorňuje dřevěná deska s nápisem \"STUDÁNKA\" a turistická značka, kolem pramene prochází mariánská poutní Skokovská stezka z Teplé do Skoků. Přístup: silnice (autem).','SIGHTSEEING',15,50.02592100,13.00466400,'https://www.estudanky.eu/foto4/5310.jpg','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:110','https://www.estudanky.eu/5310',0,'Toužim',NULL,NULL),
(465,20,'Tři prameny 1','Na západním okraji Horního Slavkova se zařezává nedlouhé údolí Sříbrného potoka. To je zajímavé tím, že jeho střední část pod koupalištěm je povětšinou suchá. Ovšem po cca 1km se situace radikálně mění v místě zvaném Tři prameny, což jsou tři mimořádně silné vývěry v těsné blízkosti vedle sebe. Přístup: pěšina (pěšky).','SIGHTSEEING',15,50.14554600,12.77957200,'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/62/Horn%C3%AD_Slavkov_Pobo%C5%BEnost_u_T%C5%99%C3%AD_pramen%C5%AF.jpg/960px-Horn%C3%AD_Slavkov_Pobo%C5%BEnost_u_T%C5%99%C3%AD_pramen%C5%AF.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:111','https://www.estudanky.eu/5638',0,'Horní Slavkov',NULL,NULL),
(468,12,'pramen Pod Kozího dílem','Pramen/studánka pod vrchem Kozí díl u Nejdku, upravená kamenná skruž. Přístup: pěšina (pěšky).','SIGHTSEEING',15,50.32450800,12.75700800,'https://www.estudanky.eu/foto6/7844.jpg','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:114','https://www.estudanky.eu/7844',0,'Nejdek',NULL,NULL),
(469,34,'Radonka - pramen Břetislav','Na první pohled vypadá tento pramen nenápadně. Je to však nejradioaktivnější povrchový vývěr v ČR. Z hlubinně zachycených zdrojů ho předstihuje pouze jáchymovský pramen Agricola (20 kBq/l), ostatní tamější zdroje mají aktivitu nižší. 3 km vzdušnou čarou leží již na německém území lázně Bad Brambach, kde vyvěrá pramen Wettinquelle s aktivitou ještě vyšší (23 kBq/l), užívaný k pitným kůrám. Stejně jakou u blízkého pramene Marie Z se projevuje mimořádná fertilita smrčinského granitu v kombinaci s příznivými tektonickými faktory.Pramen se nachází na velmi pěkném místě, snadno přístupném pěšky od vlakového nádraží v Plesné. Byl nalezen 13. června 2016 výzkumnou skupinou Přírodovědecké fakulty UK v Praze. Přístup: pěšina (pěšky).','SIGHTSEEING',15,50.20583900,12.34008100,'https://www.estudanky.eu/foto8/11000.jpg','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:115','https://www.estudanky.eu/11000',0,'Plesná',NULL,NULL),
(470,15,'pramen Dřevohryzská kyselka','Dříve byl využíván místními obyvateli při pracích v zemědělství či poutníky na cestách. Pramen byl, stejně jako nedaleká vesnice Dřevohryzy, postupně zapomenut a neudržován. V rámci záchranných prací byl pramen v roce 2012 obnoven, okolí mírně odvodněno, aby se zabránilo zaplavování pramene, byl vyčištěn od nánosů, upraveno jímání a pramen byl zastřešen. K prameni vede vyšlapaná pěšina značená jako naučná stezka po hraně lesa od křížení se silnicí Klášter Teplá - Dobrá Voda. Přístup: pěšina (pěšky).','SIGHTSEEING',15,49.98712800,12.94966200,'https://www.estudanky.eu/foto9/12815.jpg','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:116','https://www.estudanky.eu/12815',0,'Toužim',NULL,NULL),
(471,62,'pramen Mechová kyselka','Mechová kyselka vyvěrá v údolí za obcí Brtná u bezejmenného levostranného přítoku Šitbořského potoka. Kyselka je jímaná v dutém kmenu o velikosti 2 m usazeném v roce 2020. Obsah oxidu uhličitého v minerální vodě je cca 2 400 mg/l. Přístup: pěšina (pěšky).','SIGHTSEEING',15,50.00750300,12.51846900,'https://www.estudanky.eu/foto9/13384.jpg','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:117','https://www.estudanky.eu/13384',0,'Dolní Žandov',NULL,NULL),
(472,33,'pramen Maxova kyselka','Vývěr kyselky s bývalým názvem \"Maxthalsäuerling\", tedy kyselka v Maxově údolí. Tento název pochází z předválečné doby, proto byl název kyselky upraven pouze na Údolní. Kyselka vyvěrá pod parkovištěm hotelu St. Moritz, dá se k ní dojít po pěšině, která vede k restauraci Harmonie. V současné době k ní nevede žádná pěšina, od cesty je vzdálená cca 40 m. Obsach oxidu uhličitého naměřen 1490 mg/l, celková mineralizace 850 mg/l. Přístup: cesta (kolo).','SIGHTSEEING',15,49.98822500,12.69960100,'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/07/Mari%C3%A1nsk%C3%A9_L%C3%A1zn%C4%9B%2C_Lunapark%2C_pramen_Maxova_kyselka.jpg/960px-Mari%C3%A1nsk%C3%A9_L%C3%A1zn%C4%9B%2C_Lunapark%2C_pramen_Maxova_kyselka.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:118','https://www.estudanky.eu/13547',0,'Mariánské Lázně',NULL,NULL),
(473,36,'pramen Beranovská kyselka','Beranovskou kyselku popisují již roku 1609 premonstráti Tepelští, na jejichž panství vyvěrala. Kyselka je zachycena v betonové skruži. Uvnitř je zbytek starého dřevěného jímání pramene. Je stěží pitelná. Vývěr je podmáčený a nemá přímý odtok. Přístup: pěšina (pěšky).','SIGHTSEEING',15,49.93792700,12.83491800,'https://www.estudanky.eu/foto11/15130.jpg','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:119','https://www.estudanky.eu/15130',0,'Teplá',NULL,NULL),
(474,40,'pramen Bílý Halštrov','Pramen Bílý Halštrov (Elster Quelle) prýští v lesním prameništi z mělké kamenné studny jihovýchodně od Aše. Tok je na území České republiky dlouhý jen něco málo přes 11 km, ale pokračuje pod názvem Weisse Elster na území Německa, kde protéká významnými saskými městy Plavno a Lipsko, načež v sasko-anhaltském městě Halle ústí po 257 km zprava do Sály. Dnes je pramen s památníkem z roku 1898 upraven jako odpočinkové místo. Přístup: pěšina (pěšky).','SIGHTSEEING',15,50.19840000,12.27010000,'https://upload.wikimedia.org/wikipedia/commons/f/f8/Elstertal.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:120','https://www.estudanky.eu/384',0,'Hazlov',NULL,NULL),
(475,24,'pramen Horčička','Vrt KH 12 (Videnava u Lokte) byl situován v údolí Ohře za účelem ověření rozsahu oháreckého zlomového pásma v jeho jihozápadním křídle a jeho hydrogeologického charakteru. V tomto úseku oháreckého zlomového pásma byly zjištěny otevřenější drcené zóny a méně intenzivní procesy větrání žul, což umožňuje rychlý oběh podzemních vod po puklinách. Tím lze vysvětlit nízkou mineralizaci naražených tlakových vod (kolem 0,1 g*l-1) z hloubky 230 m. Přetoková vydatnost v úrovni terénu byla 0,12 l*s-1. Přístup: cesta (kolo).','SIGHTSEEING',15,50.19396900,12.78647800,'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/62/Pramen-vrt_Ho%C5%99%C4%8Di%C4%8Dka.jpg/960px-Pramen-vrt_Ho%C5%99%C4%8Di%C4%8Dka.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:121','https://www.estudanky.eu/397',0,'Loket',NULL,NULL),
(476,72,'pramen Žandováček','Minerální pramen, označovaný tímto názvem v turistických průvodcích, je u Šitbořského potoka v osadě Ždírnice (známé spíše pod názvem „Leinbruck“). Původně byl pramen této velmi dobré minerálky dostatečně vzdálen od silnice Cheb – Mariánské Lázně. Po úpravě komunikace v letech 1966-68 se silniční těleso přiblížilo bezprostředně k pramenu. Bylo vybudováno přístupové schodiště z parkoviště a upraveno okolí. Vlivem tehdy použitých materiálů pro násep i solením vozovky v zimě dochází k trvalému znečišťování pramene a jeho postupnému zániku. Přístup: silnice (autem).','SIGHTSEEING',15,50.04466600,12.51837300,'https://www.estudanky.eu/foto1/501.jpg','06:00','22:00',0,'PRAMEN',1,'EASY','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:122','https://www.estudanky.eu/501',0,'Milíkov',NULL,NULL),
(477,11,'pramen Kloubouk','Název pramene zvolen kvůli orientaci podle blízkého vrcholu Klobouk nad Jáchymovem. Přístup: pěšina (pěšky).','SIGHTSEEING',15,50.37890200,12.91990000,'https://www.estudanky.eu/foto2/1765.jpg','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:123','https://www.estudanky.eu/1765',0,'Jáchymov',NULL,NULL),
(478,84,'pramen Pluhův Bor','Pramen je součástí projektu GEOMON, který provádí geochemický monitoring malého lesního povodí. Přístup: pěšina (pěšky).','SIGHTSEEING',15,50.06280300,12.78809800,'https://www.estudanky.eu/foto2/2561.jpg','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:124','https://www.estudanky.eu/2561',0,'Nová Ves',NULL,NULL),
(479,33,'pramen Lesní studánka','Leží na svahu Zádubské výšiny, poblíže staré cesty do Mariánských Lázní. Přístup: pěšina (pěšky).','SIGHTSEEING',15,49.97551400,12.72277100,'https://www.estudanky.eu/foto3/3624.jpg','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:125','https://www.estudanky.eu/3624',0,'Mariánské Lázně',NULL,NULL),
(480,36,'pramen Kyselka U Podhorního mlýna','Pramen zmiňuje již Bohuslav Balbín ve spisu Miscelanea, v 17. století. V okolí jsou další nezachycené vývěry. Složení kyselky není známo. Původní záchyt byl do pařízku o průměru 50 cm. Dnes je zanesený odtok a tak kyselka vytváří malé jezírko. Jen několik metrů od ní leží ruiny Podhornmühle. Přístup: pěšina (pěšky).','SIGHTSEEING',15,49.98593500,12.77544400,'https://www.estudanky.eu/foto3/3704.jpg','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:126','https://www.estudanky.eu/3704',0,'Teplá',NULL,NULL),
(481,36,'pramen Agnes','Pramen byl na počátku 90. let sveden do Angerlova mlýna a stáčen pod obchodním názvem Agnes. Projekt však neměl úspěch a byl záhy zastaven. Původní jímání do pařízku je dnes zničeno a nahradila ho obyčejná trubka. Zbyla zde i malá vodárna postavená pro potřeby zaniklé stáčírny. Přístup: pěšina (pěšky).','SIGHTSEEING',15,49.98960600,12.82903300,'https://www.estudanky.eu/foto3/3705.jpg','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:127','https://www.estudanky.eu/3705',0,'Teplá',NULL,NULL),
(482,88,'pramen Mostek','Roku 2013 proběhla kompletní obnova. Aktuální stav není znám. Přístup: pěšina (pěšky).','SIGHTSEEING',15,50.17381700,12.44412600,'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/Pramen_Mostek_u_K%C5%99i%C5%BEovatky_%C5%99%C3%ADjen_2020_%282%29.jpg/960px-Pramen_Mostek_u_K%C5%99i%C5%BEovatky_%C5%99%C3%ADjen_2020_%282%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PRAMEN',1,'MEDIUM','DATAZAPAD','Přístupné_prameny_v_KK_WFL1:128','https://www.estudanky.eu/5141',0,'Křižovatka',NULL,NULL),
