(484,11,'Rozhledna Klínovec u Jáchymova','Na nejvyšší hoře Krušných hor Klínovci (1244 m n.m.) leží 80 m vysoká dominanta radiotelekomunikační věže a rozhledna. Jedná se o nejvýše položenou rozhlednu Krušných hor. Horský hotel Klínovec s rozhlednou je od 12. května 1992 chráněn jako kulturní památka. Přístupná za poplatek v otevíracích hodinách.','SIGHTSEEING',45,50.39594300,12.96789200,'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cb/Kl%C3%ADnovec_2014-06-08.jpg/960px-Kl%C3%ADnovec_2014-06-08.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','09:00','18:00',50,'ROZHLEDNA',1,'MEDIUM','DATAZAPAD','Rozhledny_v_Karlovarském_kraji_WFL1:1','https://www.bozidar.cz/cs/zajimavosti/pamatky-a-historie/rozhledna-klinovec.html',0,'č.p. 1016, 363 01 Jáchymov',NULL,NULL),
(485,89,'Rozhledna Blatenský vrch u Horní Blatné','21 metrů vysoká kamenná rozhledna byla vybudována v roce 1913 z iniciativy Spolku pro zimní sporty z Horní Blatné. Přístupná za poplatek v otevíracích hodinách.','SIGHTSEEING',45,50.40019500,12.78164400,'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/64/Blatensky_vrch1.jpg/960px-Blatensky_vrch1.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','09:00','18:00',50,'ROZHLEDNA',1,'MEDIUM','DATAZAPAD','Rozhledny_v_Karlovarském_kraji_WFL1:2','https://www.bozidar.cz/cs/zajimavosti/pamatky-a-historie/rozhledna-na-blatenskem-vrchu.html',0,'č.p. 117, 362 35 Potůčky',NULL,NULL),
(486,1,'Rozhledna Diana v Karlových Varech','Mohutná cihlová rozhledna z roku 1914 o výšce 40 m doplněná krytým dřevěným ochozem. Přístupná zdarma v otevíracích hodinách.','SIGHTSEEING',45,50.21897700,12.87225900,'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/03/Rozhledna_Diana_v_Karlov%C3%BDch_Varech.jpg/960px-Rozhledna_Diana_v_Karlov%C3%BDch_Varech.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','09:00','18:00',0,'ROZHLEDNA',1,'MEDIUM','DATAZAPAD','Rozhledny_v_Karlovarském_kraji_WFL1:3','https://dianakv.cz/cs/rozhledna-diana-karlovy-vary',0,'360 01 Karlovy Vary',NULL,NULL),
(487,33,'Rozhledna Panorama (Hamelika) v Mariánských Lázních','Rozhledna o výšce 20 m stojí v nadmořské výšce 722 metrů. Přístupná zdarma.','SIGHTSEEING',45,49.97210500,12.70955500,'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9d/Rozhledna_Panorama_Hamelika_Marianske_Lazne_A.jpg/960px-Rozhledna_Panorama_Hamelika_Marianske_Lazne_A.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','09:00','18:00',0,'ROZHLEDNA',1,'MEDIUM','DATAZAPAD','Rozhledny_v_Karlovarském_kraji_WFL1:4','https://www.marianskelazne.cz/vyznamna-mista/rozhledna-hamelika/',0,'č.p. 708, 353 01 Mariánské Lázně',NULL,NULL),
(488,12,'Rozhledna Pajndl na Tisovském vrchu','Kamenná věž o výšce 24 m včetně třímetrového hromosvodu stojí na svahu Tisovského vrchu nad Nejdkem v nadmořské výšce 976 m n.m. Přístupná zdarma.','SIGHTSEEING',45,50.34650400,12.74089600,'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/39/Rozhledna_na_Tisovsk%C3%A9m_vrchu.jpg/960px-Rozhledna_na_Tisovsk%C3%A9m_vrchu.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','09:00','18:00',0,'ROZHLEDNA',1,'MEDIUM','DATAZAPAD','Rozhledny_v_Karlovarském_kraji_WFL1:5','https://www.nejdek.cz/zajimavosti/pamatky/rozhledna-pajndl/',0,'362 22 Nejdek',NULL,NULL),
(489,17,'Rozhledna Hard v Sokolově','Osmnáctimetrová zděná věž z roku 1908. Přístupná zdarma - klíče od rozhledny na obvodním oddělení Policie ČR v sousedství rozhledny.','SIGHTSEEING',45,50.17783200,12.65682300,'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/43/Rozhledna_Hard_Sokolov_%282%29.jpg/960px-Rozhledna_Hard_Sokolov_%282%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','09:00','18:00',0,'ROZHLEDNA',1,'MEDIUM','DATAZAPAD','Rozhledny_v_Karlovarském_kraji_WFL1:6','https://www.mdksokolov.cz/pamatky/rozhledna-hard',0,'356 01 Sokolov',NULL,NULL),
