(491,1,'Goethova vyhlídka v Karlových Varech','Neogotická výletní restaurace s vyhlídkovou věží o celkové výšce 39 m. Přístupná zdarma v době provozu kavárny umístěné v patě rozhledny (pouze za příznivého počasí).','SIGHTSEEING',45,50.22407500,12.90325100,'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Karlovy_Vary_Goethova_vyhl%C3%ADdka_kv%C4%9Bten_2019_%282%29.jpg/960px-Karlovy_Vary_Goethova_vyhl%C3%ADdka_kv%C4%9Bten_2019_%282%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','09:00','18:00',0,'ROZHLEDNA',1,'MEDIUM','DATAZAPAD','Rozhledny_v_Karlovarském_kraji_WFL1:8','https://www.llpkv.cz/goethova-vyhlidka/rozhledna#rozhledna',0,'Goethova vyhlídka 244, 360 01 Karlovy Vary',NULL,NULL),
(492,2,'Bismarckova rozhledna na Zelené hoře u Chebu','Chebská rozhledna na Zelené hoře vysoká 18 m. Původně dřevěná rozhledna z roku 1891 byla v roce 1909 nahrazena odolnou kamennou stavbou. Přístupná zdarma od 31. 3. do 1. 11. denně od 9:00 do 18:00 hodin, jiné časy je nutné domluvit v turistickém infocentru v Chebu.','SIGHTSEEING',45,50.07074700,12.30640400,'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dc/Bismarckova_rozhledna_na_Zelen%C3%A9_ho%C5%99e_%283%29.JPG/960px-Bismarckova_rozhledna_na_Zelen%C3%A9_ho%C5%99e_%283%29.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','09:00','18:00',0,'ROZHLEDNA',1,'MEDIUM','DATAZAPAD','Rozhledny_v_Karlovarském_kraji_WFL1:9','https://tic.cheb.cz/cile/bismarckova-rozhledna-na-zelene-hore-637-m-n-m/',0,'350 20 Cheb',3,11),
(493,26,'Rozhledna Cibulka u Oloví','Rozhledna z ocelové konstrukce vážící 30 tun, dvě výhledové plošiny, vyšší ve výšce 26 m. Přístupná zdarma.','SIGHTSEEING',45,50.23690800,12.55786600,'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/12/Rozhledna_Cibulka_nad_Olov%C3%ADm_%282%29.jpg/960px-Rozhledna_Cibulka_nad_Olov%C3%ADm_%282%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','09:00','18:00',0,'ROZHLEDNA',1,'MEDIUM','DATAZAPAD','Rozhledny_v_Karlovarském_kraji_WFL1:10','https://www.olovi.cz/rozhledna-cibulka',0,'357 07 Oloví',NULL,NULL),
(494,86,'Panský vrch (Panská rozhledna) u Drmoulu','Vyhlídková plošina ve výšce 40 metrů. Přístupná zdarma denně od 15. března do 30. listopadu.','SIGHTSEEING',45,49.93518800,12.63826300,'https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20na%20Pansk%C3%A9m%20vrchu%20u%20Drmoulu.JPG?width=800','09:00','18:00',0,'ROZHLEDNA',1,'MEDIUM','DATAZAPAD','Rozhledny_v_Karlovarském_kraji_WFL1:11','https://www.drmoul.cz/o-drmoulu/panska-rozhledna/?ftresult_menu=rozhledna',0,'353 01 Drmoul',3,11),
(495,2,'Rozhledna Salingburg ve Františkových Lázních','Malá rozhledna (10 m) ve Františkových Lázních navržena ve stylu hradní zříceniny. Přístupná zdarma.','SIGHTSEEING',45,50.10975300,12.36013100,'https://www.frantiskovy-lazne.info/files/franlaz-item/0/339/franlaz-item_339_img_16152982213477.jpg','09:00','18:00',0,'ROZHLEDNA',1,'MEDIUM','DATAZAPAD','Rozhledny_v_Karlovarském_kraji_WFL1:12','https://www.frantiskovy-lazne.info/cs/zajimava-mista/rozhledna-salingburg_339',0,'Střížov 11, 352 01 Cheb',NULL,NULL),
(497,2,'Rozhledna Vávrova lávka s rozhlednou v Chebu','Vyhlídková věž se zavěšenou 40 m dlouhou lávkou inspirované hradním padacím mostem, výška rozhledny 10 m. Otevřena v roce 2006. Přístupná zdarma.','SIGHTSEEING',45,50.07977700,12.35997500,'https://tic.cheb.cz/wp-content/uploads/2020/12/cheb-lavka-04-d502-1.jpg','09:00','18:00',0,'ROZHLEDNA',1,'MEDIUM','DATAZAPAD','Rozhledny_v_Karlovarském_kraji_WFL1:14','https://tic.cheb.cz/cile/vyhlidkova-vez-vavrova-lavka/',0,'Kachní kámen, 350 02 Cheb',NULL,NULL),
(499,29,'Bismarckova rozhledna na Háji u Aše (Heinberg)','Mohutná vyhlídková kamenná věž o celkové výšce 34 m je nejzápadnější rozhlednou u nás. Patří mezi tzv. Bismarckovy rozhledny. Stavnostně otevřena v roce 1904. Přístupná v otevírací době - dobrovolné vstupné.','SIGHTSEEING',45,50.23344300,12.20182800,'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/67/Bismarckova_rozhledna_na_vrchu_H%C3%A1j_u_A%C5%A1e_v_roce_2015_%281%29.JPG/960px-Bismarckova_rozhledna_na_vrchu_H%C3%A1j_u_A%C5%A1e_v_roce_2015_%281%29.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','09:00','18:00',0,'ROZHLEDNA',1,'MEDIUM','DATAZAPAD','Rozhledny_v_Karlovarském_kraji_WFL1:16','https://www.frantiskovy-lazne.info/cs/vylety/bismarckova-rozhledna-haj-u-ase_351',0,'U rozhledny, 352 01 Aš',NULL,NULL),
(500,76,'Otevřené dveře v Krušných horách','Vyhlídka na hory a lesy Kraslicka. Přístupná zdarma.','SIGHTSEEING',45,50.35146300,12.54531400,'https://cdn.kudyznudy.cz/files/c2/c27ac7b4-8912-4e5a-8a23-c35c2ac40a95.jpg?v=20260926220706','09:00','18:00',0,'ROZHLEDNA',1,'MEDIUM','DATAZAPAD','Rozhledny_v_Karlovarském_kraji_WFL1:17','https://www.kudyznudy.cz/aktivity/otevrene-dvere-v-krusnych-horach',0,'Nová Ves, 358 01 Stříbrná',NULL,NULL),
(501,66,'Rozhledna Krásenský vrch u Krásna','Rozhledna o výšce 25 m s unikátním tvarem se spirálovitým schodištěm po vnějším obvodu připomínající babylonský zikkurat. Přístupná zdarma.','SIGHTSEEING',45,50.10156700,12.78641200,'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e8/Kr%C3%A1sensk%C3%BD_vrch_turistick%C3%BD_ukazatel_u_rozhledny_%281%29.jpg/960px-Kr%C3%A1sensk%C3%BD_vrch_turistick%C3%BD_ukazatel_u_rozhledny_%281%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','09:00','18:00',0,'ROZHLEDNA',1,'MEDIUM','DATAZAPAD','Rozhledny_v_Karlovarském_kraji_WFL1:18','http://www.rozhledna-krasno.cz/',0,'357 47 Krásno',NULL,NULL),
(504,20,'Rozhledna Krudum ve Slavkovském lese','Věž je vysoká 60 m, výška vyhlídkového ochozu nad zemí je 29,5 m, nadmořská výška vyhlídkového ochozu je 864,9 m. Přístupná zdarma (nutno dodržovat provozní řád a nevstupovat za nepříznivých klimatických podmínek).','SIGHTSEEING',45,50.13753700,12.72929800,'https://www.lesyloket.cz/wp-content/uploads/2021/08/sp450_5972.jpeg','09:00','18:00',0,'ROZHLEDNA',1,'MEDIUM','DATAZAPAD','Rozhledny_v_Karlovarském_kraji_WFL1:22','https://www.lesyloket.cz/rozhledna-krudum/',0,'357 31 Horní Slavkov',NULL,NULL),
(505,1,'Vyhlídka Karla IV. v Karlových Varech','Pseudogotická cihlová rozhledna v podobě minaretu se dvěma vyhlídkovými ochozy (9 a 15 metrů). Nejstarší stojící karlovarská rozhledna z roku 1876 zpřístupněná veřejnosti v roce 1877. Přístupná zdarma.','SIGHTSEEING',45,50.21631300,12.88047900,'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3e/Karlovy_Vary_vyhl%C3%ADdka_Karla_IV._z%C3%A1%C5%99%C3%AD_2022_%281%29.jpg/960px-Karlovy_Vary_vyhl%C3%ADdka_Karla_IV._z%C3%A1%C5%99%C3%AD_2022_%281%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','09:00','18:00',0,'ROZHLEDNA',1,'MEDIUM','DATAZAPAD','Rozhledny_v_Karlovarském_kraji_WFL1:23','https://www.karlovyvary.cz/cs/vyhlidka-karla-iv',0,'360 01 Karlovy Vary',NULL,NULL),
(506,11,'Boží vyhlídka u Božího Daru','Rozhlednaje vysoká 8 metrů, vyhlídková plošina se nachází ve výšce 5 metrů, která stojí ve výšce 1 099 metrů nad mořem. Přístupná zdarma od dubna do října.','SIGHTSEEING',45,50.40535800,12.93245900,'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a7/Bo%C5%BE%C3%AD_vyhl%C3%ADdka_2023-11-10_01.jpg/960px-Bo%C5%BE%C3%AD_vyhl%C3%ADdka_2023-11-10_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','09:00','18:00',0,'ROZHLEDNA',1,'MEDIUM','DATAZAPAD','Rozhledny_v_Karlovarském_kraji_WFL1:24','https://www.bozidar.cz/cs/zajimavosti/pamatky-a-historie/bozi-vyhlidka.html',0,'362 62 Jáchymov',4,10),
(508,92,'Rozhledna Třasák v Útvině u Toužimi','Dřevěná rozhledna na kamenném podstavci se nachází ve výšce 610 m n. m. Stavba je 12 m vysoká a má tři vyhlídkové plošiny (nejvyšší je ve výšce 10 m). Přístupná zdarma.','SIGHTSEEING',45,50.06767200,12.95838800,'https://cdn.kudyznudy.cz/files/17/177ead23-c23a-4c9c-a740-f3d5faea055a.jpg?v=20250225025211','09:00','18:00',0,'ROZHLEDNA',1,'MEDIUM','DATAZAPAD','Rozhledny_v_Karlovarském_kraji_WFL1:26','https://www.kudyznudy.cz/aktivity/rozhledna-trasak-v-utvine',0,'364 01 Útvina',NULL,NULL),
(509,6,'Rozhledna Karlovarská věž na hradě Hartenštejn u Bochova','Rozhledna Hartenštejn je zrekonstruovaná, 15 metrů vysoká Karlovarská věž, která je součástí volně přístupné zříceniny pozdně gotického hradu Hartenštejn. Nachází se na Zámeckém vrchu (733 m n. m.) přibližně 1 km jižně od města Bochov. Přístupná za poplatek v otevírací době Infocentra města Bochov, pouze v období duben až říjen.','SIGHTSEEING',45,50.14168300,13.03632400,'https://commons.wikimedia.org/wiki/Special:FilePath/Harten%C5%A1tejn%20-%20severn%C3%AD%20bateriov%C3%A1%20v%C4%9B%C5%BE.jpg?width=800','09:00','18:00',50,'ROZHLEDNA',1,'MEDIUM','DATAZAPAD','Rozhledny_v_Karlovarském_kraji_WFL1:27','https://www.mesto-bochov.cz/turista/pamatky/hrad-hartenstejn/',0,'364 71 Bochov',4,10),
(511,2,'Černá věž v Chebu','Hranatá věž stojí na čtvercovém základě 9 x 9 metru, je vysoká 18,5 metru. Přístupná za poplatek v otevírací době hradu.','SIGHTSEEING',45,50.08101700,12.36618400,'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7c/Cheb_-_hradn%C3%AD_%C4%8Cern%C3%A1_v%C4%9B%C5%BE_-_panoramio.jpg/960px-Cheb_-_hradn%C3%AD_%C4%8Cern%C3%A1_v%C4%9B%C5%BE_-_panoramio.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','09:00','18:00',50,'ROZHLEDNA',1,'MEDIUM','DATAZAPAD','Rozhledny_v_Karlovarském_kraji_WFL1:29','https://www.hrad-cheb.cz/cz/cerna-vez',0,'Dobrovského 21, 352 01 Cheb',NULL,NULL),
(512,5,'Hradní věž Bečov nad Teplou','Zbytky hradní věže, které dříve sloužily jako vyhlídková terasa, byly roku 2022 upraveny jako rozhledna. Vyhlídkový ochoz se nachází ve výšce 6 metrů. Přístupná za poplatek v otevírací době hradu.','SIGHTSEEING',45,50.08594600,12.83958100,'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2d/Be%C4%8Dov_nad_Teplou_hradn%C3%AD_kaple_%C4%8Derven_2023_%281%29.jpg/960px-Be%C4%8Dov_nad_Teplou_hradn%C3%AD_kaple_%C4%8Derven_2023_%281%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','09:00','18:00',50,'ROZHLEDNA',1,'MEDIUM','DATAZAPAD','Rozhledny_v_Karlovarském_kraji_WFL1:30','https://www.zamek-becov.cz/cs/informace-pro-navstevniky/hradni-vyhlidka',0,'Zámek, 364 64 Bečov nad Teplou',NULL,NULL),
(516,93,'Něžná Pivoňka','Něžná farma kromě samotných květin nabízí osvětu formou exkurzí ohledně pěstování rostlin bez ekologické zátěže. Místo, které poskytuje prostor i pro další nápady spojené s tímto oborem. Najdete ji v Hájku u Ostrova nad Ohří, hned vedle psího cvičiště. Přístup: v provozní době.','FUN',45,50.28068800,12.93256300,'https://5bf76fa48e.clvaw-cdnwnd.com/aacbcdbfbfd7115cab693e58e6056da7/200000147-57c8d57c90/700/02-4.jpg?ph=5bf76fa48e','09:00','18:00',0,'ATRAKCE',1,'EASY','DATAZAPAD','Jiné_atraktivity_v_Karlovarském_kraji_WFL1:1','https://www.neznapivonka.cz/',0,'363 01 Hájek',NULL,NULL),
(517,1,'Mayerův gloriet - vyhlídka Jelení skok','Dřevěný vyhlídkový altán Mayerův gloriet nechal postavit v roce 1804 karlovarský rodák, bohatý vídeňský obchodník Mayer na skalním suku u Jeleního skoku přímo nad lázeňským centrem města, nabízí jedinečný pohled z ptačí perspektivy na lázeňské centrum města.','SIGHTSEEING',45,50.22270000,12.87990400,'https://commons.wikimedia.org/wiki/Special:FilePath/KV-Pavillon-Mayer-1.jpg?width=800','09:00','18:00',0,'ATRAKCE',1,'EASY','DATAZAPAD','Jiné_atraktivity_v_Karlovarském_kraji_WFL1:2','https://www.karlovyvary.cz/cs/mayeruv-gloriet',0,'360 01 Karlovy Vary',NULL,NULL),
(518,67,'Mattoniho lázně Kyselka','Idylické výletní místo s neopakovatelnou lesnatou krajinou.','SIGHTSEEING',45,50.25922600,13.00016100,'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f8/L%C3%A1zn%C4%9B_Kyselka_Jind%C5%99ich%C5%AFv_dv%C5%AFr_leden_2022_%281%29.jpg/960px-L%C3%A1zn%C4%9B_Kyselka_Jind%C5%99ich%C5%AFv_dv%C5%AFr_leden_2022_%281%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','09:00','18:00',0,'ATRAKCE',1,'EASY','DATAZAPAD','Jiné_atraktivity_v_Karlovarském_kraji_WFL1:4','https://www.kudyznudy.cz/aktivity/mattoniho-lazne-kyselka',0,'362 72 Kyselka',NULL,NULL),
(519,30,'Trojstátí','Naučná stezka Na cestě k Trojstátí vede z Hranic na Trojstátí Čech, Bavorska a Saska a má přírodovědně-historický ráz. Celková délka stezky měří přibližně 18 km a obsahuje celkem 9 hlavních zastavení. Stezku k Trojstátí doplňuje Stezka kamenů.','PARK',45,50.31821100,12.10106100,'https://cdn.kudyznudy.cz/files/26/26af564d-4b7f-4ceb-ac58-6dde99d4c7a6.jpg?v=20250311071004','09:00','18:00',0,'ATRAKCE',1,'EASY','DATAZAPAD','Jiné_atraktivity_v_Karlovarském_kraji_WFL1:5','https://www.kudyznudy.cz/aktivity/naucna-stezka-na-ceste-k-trojstati',0,'Trojstátí, 351 24 Hranice',NULL,NULL),
(520,33,'Boheminium park','Čtvrtý největší park miniatur v Evropě, unikátní nejen svým jedinečným zasazením do přírody, ale i širokou nabídkou do detailu propracovaných modelů českých památek v měřítku 1:25. Přístup: v provozní době, zpoplatněný.','FUN',45,49.97112200,12.72060500,'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/46/Vstup_Park_Bohemium_Marianske_L.jpg/960px-Vstup_Park_Bohemium_Marianske_L.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','09:00','18:00',100,'ATRAKCE',1,'EASY','DATAZAPAD','Jiné_atraktivity_v_Karlovarském_kraji_WFL1:6','https://www.boheminium.cz/',0,'č.p. 665, 353 01 Mariánské Lázně',NULL,NULL),
(521,1,'Zámecká věž','Od roku 2022 je Zámecká věž otevřena návštěvníkům. Najdete zde expozici Great Spa Towns of Europe připomínající další důležitý milník Karlových Varů – zápis města spolu s dalšími deseti evropskými městy na Seznam světového kulturního a přírodního dědictví UNESCO. Jedinečný výhled si nejlépe vychutnáte z kavárny při skvělé kávě z lokální pražírny. Přístup: v provozní době.','SIGHTSEEING',45,50.22372800,12.88318600,'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/Tr%C5%BEn%C3%AD_kolon%C3%A1da_a_Z%C3%A1meck%C3%A1_v%C4%9B%C5%BE.jpg/960px-Tr%C5%BEn%C3%AD_kolon%C3%A1da_a_Z%C3%A1meck%C3%A1_v%C4%9B%C5%BE.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','09:00','18:00',0,'ATRAKCE',1,'EASY','DATAZAPAD','Jiné_atraktivity_v_Karlovarském_kraji_WFL1:7','https://zameckavez.cz/',0,'Zámecký vrch 431/2, 360 01 Karlovy Vary',NULL,NULL),
(523,11,'Lanovka na Klínovec','Čtyřsedačková lanovka krytá oranžovými bublinami vás vyveze až na vrchol Klínovce. Přístup: v provozní době, zpoplatněný.','FUN',45,50.38512800,12.94315900,'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/50/Lanovka_Klinovec.jpg/960px-Lanovka_Klinovec.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','09:00','18:00',100,'ATRAKCE',1,'EASY','DATAZAPAD','Jiné_atraktivity_v_Karlovarském_kraji_WFL1:9','https://klinovec.cz/aktualne-z-klinovce/',0,'č.p. 1065, 362 51 Jáchymov',NULL,NULL),
(524,1,'Motýlí dům','Setkáte se zde s nejkrásnějšími motýly z celého světa - např. z Thajska, Filipín, deštných pralesů Jižní Ameriky či Mexika. Letová zóna se rozkládá na ploše 100 m2 a vy si budete moci prohlédnout tyto krasavce z naprosté blízkosti a v absolutním kontaktu. Nenajdete zde totiž žádné bariéry mezi hosty a motýly. Přístup: Dle otevírací/provozní doby Motýlího domu (možno dohledat na webových stránkách).','FUN',45,50.21874100,12.87169800,NULL,'09:00','18:00',100,'ATRAKCE,ZOO',1,'EASY','DATAZAPAD','Jiné_atraktivity_v_Karlovarském_kraji_WFL1:10','https://dianakv.cz/cs/motyli-dum',0,'Vrch přátelství 5/1, 360 01 Karlovy Vary',NULL,NULL),
(525,1,'Festivalový most v Karlových Varech','Festivalový most mezi Císařskými lázněmi a Grandhotelem Pupp. Festivalový most se navrátil k původní historické podobě. Jeho kované zábradlí bylo zhotoveno jako přesná kovářská replika toho historického.','SIGHTSEEING',45,50.21878800,12.88057900,NULL,'09:00','18:00',0,'ATRAKCE',1,'EASY','DATAZAPAD','Jiné_atraktivity_v_Karlovarském_kraji_WFL1:11','https://www.kudyznudy.cz/aktivity/festivalovy-most-v-karlovych-varech',0,'Goethova stezka, 360 01 Karlovy Vary',NULL,NULL),
(526,1,'Fotopoint v Karlových Varech','Fotopoint poblíž Mlýnské kolonády na Lázeňské ulici má podobu nápisu I love Vary se srdíčkem a znakem pro stupně Celsia, což odkazuje ke zdejším horkým pramenům.','SIGHTSEEING',45,50.22515300,12.88240300,'https://cdn.kudyznudy.cz/files/9b/9b2d6621-edab-4ec5-bcec-ff062d8917ae.jpg?v=20260926143117','09:00','18:00',0,'ATRAKCE',1,'EASY','DATAZAPAD','Jiné_atraktivity_v_Karlovarském_kraji_WFL1:12','https://www.kudyznudy.cz/aktivity/fotopoint-v-karlovych-varech',0,'360 01 Karlovy Vary',NULL,NULL),
(527,54,'Vysoký smrk pod Favoritem','Vysoký smrk pod Favoritem je památný strom Smrk ztepilý, který roste v blízkosti kamenného kříže cca 150 m západně od zámečku Favorit. Jedná se o nejvyšší památný strom v Karlovarském kraji.','PARK',45,50.30363400,12.60265900,'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/eb/%C5%A0indelov%C3%A1_vysok%C3%BD_smrk_pod_Favoritem.jpg/960px-%C5%A0indelov%C3%A1_vysok%C3%BD_smrk_pod_Favoritem.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','09:00','18:00',0,'ATRAKCE',1,'EASY','DATAZAPAD','Jiné_atraktivity_v_Karlovarském_kraji_WFL1:13','https://www.kudyznudy.cz/aktivity/vysoky-smrk-pod-favoritem',0,'358 01 Šindelová',NULL,NULL),
(529,1,'Mini zoo Diana','Mini zoo Diana hostí göttingenská mini prasátka, shetlandské poníky, kamerunské kozičky, klasického páva a sněhobílého páva Frostyho. Přístup k ohradě je volný a bezplatný.','FUN',120,50.21876400,12.87121400,NULL,'09:00','17:00',0,'ZOO',1,'EASY','DATAZAPAD','ZOO_a_zooparky_v_Karlovarském_kraji_WFL1:1','https://dianakv.cz/cs/mini-zoo',0,'Vrch přátelství 5/1, 360 01 Karlovy Vary',NULL,NULL),
(530,14,'Ekocentrum Ostrov','Najdete zde přes 50 různých druhů zvířat - kajmany, želvy, dravé i exotické ptactvo, drobné šelmy, ryby atd. Koná se zde přes 20 zájmových kroužků, příměstské tábory a vzdělávací programy. Přístup: V odpoledních hodinách (mimo časy pravidelných zájmových kroužků) si můžete volně prohlédnout vnitřní i venkovní výběhy.','FUN',120,50.30565800,12.93554200,NULL,'09:00','17:00',0,'ZOO',1,'EASY','DATAZAPAD','ZOO_a_zooparky_v_Karlovarském_kraji_WFL1:2','https://www.mddmostrov.cz/ekocentrum',0,'Klášterní 1418, 363 01 Ostrov',NULL,NULL),
(531,3,'Zookoutek Amerika','Expozice zvířat se nachází v lesoparku Amerika, nedaleko Františkových Lázní. V poslední letech prošla revitalizací. Ve výbězích a voliérách se nacházejí koně, lamy, kachny, sovy sněžné i mývalové. Přístup: Volně přístupné bez omezení času.','FUN',120,50.11163600,12.33345600,'https://cdn.kudyznudy.cz/files/85/85fc2eaf-f087-4e88-a0e7-d6fce9a09661.jpg?v=20260928142121','06:00','22:00',0,'ZOO',1,'EASY','DATAZAPAD','ZOO_a_zooparky_v_Karlovarském_kraji_WFL1:3','https://www.kudyznudy.cz/aktivity/maly-zoopark-amerika-u-frantiskovych-lazni',0,'Jezerní 29/8, 351 01 Františkovy Lázně',NULL,NULL),
(532,78,'Zookoutek Hory','Je zde možné z víceúčelové věže spatřit dančí a mufloní zvěř, vzácného černého daňka nebo téměř krotké jeleny, které si návštěvník může i pohladit. Dále je zde možné si prohlédnout koně trénované na parkurové závody. Přístup: Volně přístupné bez omezení času.','FUN',120,50.20233300,12.79108900,'https://9fce0af803.clvaw-cdnwnd.com/6fae101f71394bd01d193dfab914a5e7/200000115-839818495e/700/IMG_1519.JPG?ph=9fce0af803','06:00','22:00',0,'ZOO',1,'EASY','DATAZAPAD','ZOO_a_zooparky_v_Karlovarském_kraji_WFL1:4','https://www.farma-hory.cz/',0,'č.p. 105, 360 01 Hory',NULL,NULL),
(533,33,'Obůrka Hvozd','Obůrka Hvozd se nachází nedaleko centra Mariánských lázní. Z přistaveného posedu zde můžete pozorovat daňky a jeleny. Do obory je vstup zakázán. Přístup: Okolí obory volně přístupné bez omezení.','FUN',120,49.96899700,12.71866400,'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/db/Mari%C3%A1nsk%C3%A9_L%C3%A1zn%C4%9B_obora_Hvozd_%282%29.jpg/960px-Mari%C3%A1nsk%C3%A9_L%C3%A1zn%C4%9B_obora_Hvozd_%282%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'ZOO',1,'EASY','DATAZAPAD','ZOO_a_zooparky_v_Karlovarském_kraji_WFL1:5','https://www.kudyznudy.cz/aktivity/oburka-hvozd-nad-centrem-marianskych-lazni',0,'353 01 Mariánské Lázně',NULL,NULL),
(534,1,'Obora Linhart','Obora Svatý Linhart se rozkládá na ploše 40 hektarů. Kromě klasické pozorovatelny nabízí i ojedinělý pohled na zvířata a krajinu, a to shora. K tomu účelu slouží soustava můstků, která místy vyvede stezku až do šestimetrové výšky. Přístup: Volně přístupné bez omezení času.','FUN',120,50.21465100,12.85404300,'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/95/Svat%C3%BD_Linhart_Lu%C4%8Dn%C3%AD_rybn%C3%ADk_v_obo%C5%99e_da%C5%88k%C5%AF_%282%29.jpg/960px-Svat%C3%BD_Linhart_Lu%C4%8Dn%C3%AD_rybn%C3%ADk_v_obo%C5%99e_da%C5%88k%C5%AF_%282%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'ZOO',1,'EASY','DATAZAPAD','ZOO_a_zooparky_v_Karlovarském_kraji_WFL1:6','https://www.llpkv.cz/svaty-linhart/obora-svaty-linhart',0,'Sovova stezka, 360 01 Karlovy Vary',NULL,NULL),
(536,35,'Stanice pro záchranu živočichů SOOS','Částečně zpřístupněná stanice pro péči o poraněná zvířata. Prohlédnout si zde můžete především ptáky a menší savce, které ze zdravotních důvodů není možné vrátit do volné přírody. Přístup: Dle otevírací/provozní doby stanice.','FUN',120,50.14626400,12.40404600,'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/51/Soos_stanice_pro_z%C3%A1chranu_%C5%BEivo%C4%8Dich%C5%AF_b%C5%99ezen_2024.jpg/960px-Soos_stanice_pro_z%C3%A1chranu_%C5%BEivo%C4%8Dich%C5%AF_b%C5%99ezen_2024.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','09:00','17:00',150,'ZOO',1,'EASY','DATAZAPAD','ZOO_a_zooparky_v_Karlovarském_kraji_WFL1:8','https://www.muzeum-frantiskovylazne.cz/index.php/cz/stanice-pro-zachranu-zivocichu',0,'Kateřina 39, 351 34 Skalná',NULL,NULL),
(537,94,'Minizoo statek Bernard','V zookoutku na Statku Bernard si návštěvníci mohou prohlédnout několik domácích zvířat – chováme zde ovce, kozy, prase, králíky, slepice, husy a také morče. Hlavně děti budou nadšené z toho, že mohou vstoupit přímo do výběhu a zvířata si pohladit a nakrmit, aniž by mezi nimi byl plot. Přístup: Dle otevírací/provozní doby statku.','FUN',120,50.19487200,12.67413700,'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/41/Kr%C3%A1lovsk%C3%A9_Po%C5%99%C3%AD%C4%8D%C3%AD_statek_Bernard_%285%29.jpg/960px-Kr%C3%A1lovsk%C3%A9_Po%C5%99%C3%AD%C4%8D%C3%AD_statek_Bernard_%285%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','09:00','17:00',0,'ZOO,FARMA',1,'EASY','DATAZAPAD','ZOO_a_zooparky_v_Karlovarském_kraji_WFL1:9','https://www.statek-bernard.cz/zoo-koutek',0,'Šachetní 135, 357 41 Královské Poříčí',NULL,NULL),
(538,87,'Vesnická zvířecí farma','Vesnická zvířecí farma představuje prasata Kune kune, afrického pštrosa dvouprstého, holandské kozy, ouessanské ovce, lamy krotké, bantamky, kéně, krávy a další zvířata, která budou postupně přibývat. Návštěvníci mají možnost koupit krmení. Přístup: Každý den od 10:00 do 20:00 h.','FUN',120,49.94984300,12.73683000,NULL,'10:00','20:00',0,'ZOO',1,'EASY','DATAZAPAD','ZOO_a_zooparky_v_Karlovarském_kraji_WFL1:10','https://www.facebook.com/groups/1798897140897136/about',0,'č.p. 17, 353 01 Vlkovice',NULL,NULL),
