(640,5,'Bečovská botanická zahrada','Krajina Bečovska je ojedinělým příkladem kulturní krajiny s vlastní identitou, v níž se prolínají specifické krajinné prvky, výskyt zajímavých a ohrožených druhů rostlin a živočichů a doklady několika staletí kontinuální kulturní činnosti člověka.','PARK',60,50.08140100,12.82642600,'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/Botanical_Garden_in_Be%C4%8Dov_nad_Teplou_06.jpg/960px-Botanical_Garden_in_Be%C4%8Dov_nad_Teplou_06.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','09:00','18:00',60,'ZAHRADA',1,'EASY','DATAZAPAD','Botanické_zahrady_a_arboreta_v_Karlovarském_kraji_WFL1:1','https://www.becovskabotanicka.cz/',0,'Tovární 478, 364 64 Bečov nad Teplou',NULL,NULL),
