(732,2,'Památník obětem železné opony','Památník představuje roztržená pouta a je věnovaný lidem, kteří zemřeli v letech 1948 až 1989 na hranici při pokusu emigrovat z tehdejšího Československa.','SIGHTSEEING',20,50.04370800,12.34482600,'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f1/Svat%C3%BD_K%C5%99%C3%AD%C5%BE_pam%C3%A1tn%C3%ADk_%C5%BDelezn%C3%A9_opony_%C4%8Derven_2023_%284%29.jpg/960px-Svat%C3%BD_K%C5%99%C3%AD%C5%BE_pam%C3%A1tn%C3%ADk_%C5%BDelezn%C3%A9_opony_%C4%8Derven_2023_%284%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'PIETNI',1,'EASY','DATAZAPAD','Vojenské_a_pietní_památky_v_KVK_WFL1:1','https://www.kudyznudy.cz/aktivity/pamatnik-obetem-zelezne-opony-u-chebu',0,'Cheb',NULL,NULL),
(733,17,'Památník bitvy u Sokolova','Pomník byl postaven na paměť prvního bojového vystoupení 1. československého samostatného praporu v bitvě u Sokolova 8. března 1943 v tehdejším Sovětském svazu. V podstavci je symbolicky uložena prsť z bojiště.','SIGHTSEEING',20,50.17972200,12.64253800,'https://cdn.kudyznudy.cz/files/bb/bb9d323b-151d-4e6a-848c-bfb9c5b810cf.jpg?v=20250228043152','06:00','22:00',0,'PIETNI',1,'EASY','DATAZAPAD','Vojenské_a_pietní_památky_v_KVK_WFL1:2','https://www.kudyznudy.cz/aktivity/pamatnik-bitvy-u-sokolova-v-sokolove',0,'Sokolov',NULL,NULL),
(734,2,'Památník 1. pěší divize Americké armády - The Big Red One','Mramorová pyramida s 639 jmény amerických vojáků, kteří padli při osvobozování Chebu na jaře 1945.','SIGHTSEEING',20,50.08461000,12.44961700,'https://cdn.kudyznudy.cz/files/d0/d03dea4c-6aa1-4709-b6bb-36fde3213a36.jpg?v=20250708232529','06:00','22:00',0,'PIETNI',1,'EASY','DATAZAPAD','Vojenské_a_pietní_památky_v_KVK_WFL1:3','https://www.kudyznudy.cz/aktivity/pamatnik-americkym-vojakum-ypsilonka-u-chebu',0,'Cheb',NULL,NULL),
(735,6,'Pomník obětem světových válek','12 m vysoký pomník ve tvaru obelisku či komolého jehlanu je vystavěn ze žulových kvádrů a je těžký 165 tun. Na jednotlivých stranách pomníku jsou umístěny žulové desky se 107 jmény padlých.','SIGHTSEEING',20,50.13529200,13.08651900,'https://commons.wikimedia.org/wiki/Special:FilePath/Pomn%C3%ADk%20ob%C4%9Btem%20sv%C4%9Btov%C3%BDch%20v%C3%A1lek%20v%20%C3%9Adr%C4%8Di%20%28Q94443785%29%2001.jpg?width=800','06:00','22:00',0,'PIETNI',1,'EASY','DATAZAPAD','Vojenské_a_pietní_památky_v_KVK_WFL1:4','https://www.mesto-bochov.cz/turista/pamatky/pomnik-obetem-1-svetove-valky/',0,'Bochov',NULL,NULL),
(736,2,'Zbrojnice','Městská zbrojnice v Chebu je historická budova, která vznikla v roce 1490 spojením dvou domů a později byla rozšířena přístavbou dalších dvou domů v letech 1551 a 1552. Její krov je architektonicky zajímavý, kombinuje pozdně středověké a renesanční prvky, a je považován za jeden z nejstarších příkladů ležaté stolice v ČR.','SIGHTSEEING',20,50.07832300,12.36656800,'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e5/Cheb_-_m%C4%9Bstsk%C3%BD_dv%C5%AFr_-_zbrojnice_%28%C4%8Dp._51%29_%284%29.jpg/960px-Cheb_-_m%C4%9Bstsk%C3%BD_dv%C5%AFr_-_zbrojnice_%28%C4%8Dp._51%29_%284%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PIETNI',1,'EASY','DATAZAPAD','Vojenské_a_pietní_památky_v_KVK_WFL1:5','http://encyklopedie.cheb.cz/cz/encyklopedie/mestska-zbrojnice',0,'Cheb',NULL,NULL),
(737,24,'Městské opevnění v Lokti','Městské opevnění v Lokti bylo postupně budováno od 13. století, k původnímu gotickému jádru s kamennými hradbami a baštami byly v 17. století přidány barokní bastiony. Po zániku jeho obranné funkce bylo v roce 1840 zrušeno a části byly rozprodány, avšak v 70. letech 20. století začala jeho obnova. Dodnes jsou zachovány části hradeb (např. Černá věž, Robičská věž) a některé bašty, které umožňují nahlédnout do historie obranného systému města.','SIGHTSEEING',20,50.18549600,12.75540400,'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/Loket_M%C4%9Bstsk%C3%A9_opevn%C4%9Bn%C3%AD_star%C3%A1_ba%C5%A1ta_%281%29.jpg/960px-Loket_M%C4%9Bstsk%C3%A9_opevn%C4%9Bn%C3%AD_star%C3%A1_ba%C5%A1ta_%281%29.jpg?utm_source=cs.wikipedia.org&utm_campaign=api&utm_content=thumbnail','06:00','22:00',0,'PIETNI',1,'EASY','DATAZAPAD','Vojenské_a_pietní_památky_v_KVK_WFL1:6','https://www.loket.cz/mestske-opevneni/d-5047',0,'Loket',NULL,NULL),
(738,64,'Pomník umučených žen (památník pochodu smrti)','Památník je na místě, kde v posledních měsících druhé světové války zemřelo vyčerpáním dvanáct žen, které byly součástí pochodu smrti. Tento pochod smrti směřoval z koncentračního tábora a v závěru války prošel Slavkovským lesem, přičemž ženy byly nuceny jít pěšky po dlouhé cestě z Osvětimi.','SIGHTSEEING',20,50.08467100,12.71134300,'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a2/Pam%C3%A1tn%C3%ADk_umu%C4%8Den%C3%BDch_%C5%BEen.jpg/960px-Pam%C3%A1tn%C3%ADk_umu%C4%8Den%C3%BDch_%C5%BEen.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'PIETNI',1,'EASY','DATAZAPAD','Vojenské_a_pietní_památky_v_KVK_WFL1:7','https://www.tourismato.cz/pomnik-umucenych-zen-p105695',0,'Rovná',NULL,NULL),
(739,40,'Pomník obětem 1. světové války','Pomník v podobě mohyly z hrubě opracovaného lomového kamene (otovská žula). Stojí na kruhovém podstavci, na který navazuje kruhová základna s deseti nápisovými deskami z leštěné žuly nesoucí dohromady 141 jmen padlých. Jeden z nejrozměrnějších a architektonicky nejlépe zpracovaných pomníků svého druhu v regionu. Odhalen 12. srpna 1923.','SIGHTSEEING',20,50.15383500,12.27462400,'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/Hazlov_pomn%C3%ADk_ob%C4%9Btem_1._sv._v%C3%A1lky_leden_2020_%281%29.jpg/960px-Hazlov_pomn%C3%ADk_ob%C4%9Btem_1._sv._v%C3%A1lky_leden_2020_%281%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'PIETNI',1,'EASY','DATAZAPAD','Vojenské_a_pietní_památky_v_KVK_WFL1:8','https://pamatkovykatalog.cz/pomnik-obetem-i-svetove-valky-11219279',0,'Hazlov',NULL,NULL),
(740,29,'Pomník padlým v 1. a 2. světové válce','Pietní místo padlým v první a druhé světové válce stojící na volně přístupném prostranství u plotu přilehlé nemovitosti ev.č. 67 v Dolních Pasekách. Kámen s deskami padlých.','SIGHTSEEING',20,50.23536700,12.23711900,'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/Doln%C3%AD_Paseky_pomn%C3%ADk_padl%C3%BDm_v_1._sv._v%C3%A1lce_%282%29.jpg/960px-Doln%C3%AD_Paseky_pomn%C3%ADk_padl%C3%BDm_v_1._sv._v%C3%A1lce_%282%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'PIETNI',1,'EASY','DATAZAPAD','Vojenské_a_pietní_památky_v_KVK_WFL1:9','https://www.drobnepamatky.cz/node/52389',0,'Aš',NULL,NULL),
(741,56,'Pomník padlým v 1. světové válce','Pomník padlým v 1. světové válce v Novém Kostel (součást obce Kopanina) je kamenný monument s válečným křížem na vrcholu a reliéfem kříže na podstavci. Monument byl postaven v roce 1925 místním Spolkem vysloužilých vojáků při hlavní silnici ve farní zahradě naproti kostelu Nejsvětější Trojice.','SIGHTSEEING',20,50.19426900,12.47209900,'https://commons.wikimedia.org/wiki/Special:FilePath/Kriegerdenkmal%20Kopanina.jpg?width=800','06:00','22:00',0,'PIETNI',1,'EASY','DATAZAPAD','Vojenské_a_pietní_památky_v_KVK_WFL1:10','https://evidencevh.mo.gov.cz/Evidence/detail-hrobu-ci-mista?id=CZE4102-40601',0,'Nový Kostel',NULL,NULL),
(742,17,'Památník vojenské přísahy pod Krudumem','Památník vojenské přísahy u Hruškové byl postaven v roce 1947 v tehdejším Vojenském újezdu Prameny na počest místních příslušníků předválečných jednotek SOS (Stráž obrany státu), kteří padli při ochraně hranic těsně před zabráním Sudet Německem.','SIGHTSEEING',20,50.14811000,12.72635600,'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7b/Hru%C5%A1kov%C3%A1_Pam%C3%A1tn%C3%ADk_vojensk%C3%A9_p%C5%99%C3%ADsahy_pod_Krudumem.jpg/960px-Hru%C5%A1kov%C3%A1_Pam%C3%A1tn%C3%ADk_vojensk%C3%A9_p%C5%99%C3%ADsahy_pod_Krudumem.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','06:00','22:00',0,'PIETNI',1,'EASY','DATAZAPAD','Vojenské_a_pietní_památky_v_KVK_WFL1:11','https://www.drobnepamatky.cz/node/24046',0,'Sokolov',NULL,NULL);
